import React, { useState, useEffect, useRef } from 'react';
import ConfettiExplosion from 'react-confetti-explosion';
import useGame from '../hooks/useGame';
import useLocalStorage from '../hooks/useLocalStorage';
import useSound from '../hooks/useSound';
import { translations } from '../config/translations';
import { hasValidMovesFlat, isValidPairFlat } from '../utils/gameLogic';
import FeedbackModal from './FeedbackModal';
import { useLanguage } from '../App';

function GameBoard({ onHome, currentLanguage, onGameComplete, onTutorial }) {
  const {
    gameState,
    bestScore,
    selectedCellIndex,
    hintHighlights,
    showWin,
    showGameOver,
    showStageStart,
    initializeGame,
    selectCell,
    processMatch,
    addRow,
    useHint: getHint,
    nextStage,
    retryStage,
    retryCurrentGame,
    goHome,
    clearSelection
  } = useGame();

  const [wrongPairCells, setWrongPairCells] = useState([]);
  const [blockingCells, setBlockingCells] = useState([]);
  const [confettiCells, setConfettiCells] = useState([]);
  const [matchLines, setMatchLines] = useState([]);

  const [pathBlockedMessage, setPathBlockedMessage] = useState('');
  const [showPathBlocked, setShowPathBlocked] = useState(false);
  const { language, setLanguage } = useLanguage();
  const [showLangDropdown, setShowLangDropdown] = useState(false);
  const [soundEnabled, setSoundEnabled] = useLocalStorage('soundEnabled', true);
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [showUnlockToast, setShowUnlockToast] = useState(false);
  const [unlockToastMessage, setUnlockToastMessage] = useState('');
  const [lowMatchShown, setLowMatchShown] = useState(false);

  const [showGoalNotification, setShowGoalNotification] = useState(false);
  const [showPauseModal, setShowPauseModal] = useState(false);
  const [showStageStartModal, setShowStageStartModal] = useState(false);
  const [stageStartMessage, setStageStartMessage] = useState('');
  const [showHintTooltip, setShowHintTooltip] = useState(false);
  const [handPosition, setHandPosition] = useState({ top: 0, left: 0 });
  const [isHandTapping, setIsHandTapping] = useState(false);
  const [showFeedbackModal, setShowFeedbackModal] = useState(false);

  const sound = useSound();
  const inactivityTimer = useRef(null);
  const handAnimationInterval = useRef(null);

  const effectCanvasRef = useRef(null);

  const languages = [
    { code: 'en', name: 'English' },
    { code: 'hi', name: 'हिन्दी' },
    { code: 'kn', name: 'ಕನ್ನಡ' },
    { code: 'ta', name: 'தமிழ்' },
    { code: 'te', name: 'తెలుగు' },
    { code: 'ml', name: 'മലയാളം' },
    { code: 'mr', name: 'मराठी' }
  ];

  const t = (key) => translations[language]?.[key] || translations.en[key] || key;

  // Initialize game if no state exists or board is missing
  useEffect(() => {
    if (!gameState || !gameState.board) {
      const stage = gameState?.stage || 1;
      initializeGame(stage);
    }
  }, [gameState, initializeGame]);

  // Handle retry from home screen
  useEffect(() => {
    const handleRetryFromHome = () => {
      retryCurrentGame();
    };

    window.addEventListener('retryFromHome', handleRetryFromHome);
    return () => window.removeEventListener('retryFromHome', handleRetryFromHome);
  }, [retryCurrentGame]);



  // Reset low match notification flag when stage changes
  useEffect(() => {
    setLowMatchShown(false);
  }, [gameState?.stage]);

  // Show big confetti on stage completion and handle stage transition
  useEffect(() => {
    if (showWin) {
      if (soundEnabled) sound.win();

      // Step 1: Show win message for 2 seconds
      const hideWinTimeout = setTimeout(() => {
        // Step 2: Wait a bit then proceed to next stage
        const proceedTimeout = setTimeout(() => {
          nextStage(); // This will trigger showStageStart in the hook
        }, 500);

        return () => clearTimeout(proceedTimeout);
      }, 2000);

      return () => clearTimeout(hideWinTimeout);
    }
  }, [showWin, soundEnabled, sound, nextStage]);

  // Handle stage start modal when showStageStart becomes true
  useEffect(() => {
    if (showStageStart) {
      const nextStageNum = gameState.stage;
      setStageStartMessage(`${t('get_ready')}\n${t('stage')} ${nextStageNum}`);
      setShowStageStartModal(true);

      const hideStageStartTimeout = setTimeout(() => {
        setShowStageStartModal(false);
      }, 2000);

      return () => clearTimeout(hideStageStartTimeout);
    } else {
      setShowStageStartModal(false);
    }
  }, [showStageStart, gameState?.stage, t]);

  // Show goal notification on game start
  useEffect(() => {
    if (gameState?.stage === 1) {
      setShowGoalNotification(true);
      setTimeout(() => setShowGoalNotification(false), 4000);
    }
  }, [gameState?.stage]);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (showLangDropdown && !event.target.closest('.lang-dropdown')) {
        setShowLangDropdown(false);
      }
    };

    document.addEventListener('click', handleClickOutside);
    return () => document.removeEventListener('click', handleClickOutside);
  }, [showLangDropdown]);

  // Test event listeners
  useEffect(() => {
    const handleTestUnlockToast = (event) => {
      if (soundEnabled) {
        const toastSound = document.querySelector(`#toast-sound-${language}`);
        if (toastSound) {
          toastSound.play().catch(() => { });
        }
      }
      setUnlockToastMessage(event.detail.message || t('unlock_toast_message').replace('{}', '2'));
      setShowUnlockToast(true);
      setTimeout(() => setShowUnlockToast(false), 2000);
    };

    const handleTestSlideToast = (event) => {
      setToastMessage(event.detail.message);
      setShowToast(true);
      setTimeout(() => setShowToast(false), 3000);
    };

    window.addEventListener('testUnlockToast', handleTestUnlockToast);
    window.addEventListener('testSlideToast', handleTestSlideToast);

    return () => {
      window.removeEventListener('testUnlockToast', handleTestUnlockToast);
      window.removeEventListener('testSlideToast', handleTestSlideToast);
    };
  }, [language, soundEnabled, t]);

  // Update toast message when language changes
  useEffect(() => {
    if (showUnlockToast) {
      setUnlockToastMessage(t('unlock_toast_message').replace('{}', '2'));
    }
    if (showToast) {
      setToastMessage(t('add_numbers_blurb'));
    }
  }, [language, t, showUnlockToast, showToast]);

  // Inactive user detection
  useEffect(() => {
    const resetInactivityTimer = () => {
      if (inactivityTimer.current) {
        clearTimeout(inactivityTimer.current);
      }
      setShowHintTooltip(false);
      if (handAnimationInterval.current) {
        clearInterval(handAnimationInterval.current);
      }

      inactivityTimer.current = setTimeout(() => {
        if (gameState?.hintsLeft > 0) {
          showHintPrompt();
        }
      }, 10000); // 10 seconds of inactivity
    };

    const showHintPrompt = () => {
      const hintBtn = document.querySelector('#hint-btn');
      if (!hintBtn) return;

      const rect = hintBtn.getBoundingClientRect();
      const containerRect = document.querySelector('.w-full.h-full.bg-blue-50').getBoundingClientRect();

      const top = rect.top - containerRect.top + 20;
      const left = rect.left - containerRect.left + (rect.width / 2) - 20;

      setHandPosition({ top, left });
      setShowHintTooltip(true);

      // Play hint sound
      if (soundEnabled) {
        if (['kn', 'ta', 'te', 'ml', 'mr'].includes(language)) {
          const hintSound = document.querySelector(`#hint-sound-${language}`);
          if (hintSound) {
            hintSound.play().catch(() => { });
          }
        } else if (['en', 'hi'].includes(language)) {
          // Use TTS for English and Hindi
          if ('speechSynthesis' in window) {
            speechSynthesis.cancel();
            const utterance = new SpeechSynthesisUtterance(t('hint_blurb'));
            utterance.lang = language === 'hi' ? 'hi-IN' : 'en-US';
            speechSynthesis.speak(utterance);
          }
        }
      }

      // Animate hand tapping
      const animateHand = () => {
        setIsHandTapping(true);
        setTimeout(() => setIsHandTapping(false), 600);
      };

      handAnimationInterval.current = setInterval(animateHand, 1200);
      animateHand();
    };

    const handleActivity = () => {
      resetInactivityTimer();
    };

    // Add event listeners for user activity
    document.addEventListener('click', handleActivity);
    document.addEventListener('touchstart', handleActivity);

    resetInactivityTimer();

    return () => {
      if (inactivityTimer.current) clearTimeout(inactivityTimer.current);
      if (handAnimationInterval.current) clearInterval(handAnimationInterval.current);
      document.removeEventListener('click', handleActivity);
      document.removeEventListener('touchstart', handleActivity);
    };
  }, [gameState?.hintsLeft, language, soundEnabled]);

  // Check for low matches and show notifications - separate from add button logic
  useEffect(() => {
    if (!gameState?.board || !Array.isArray(gameState.board)) return;

    const validPairs = [];

    // Find all valid pairs to count matches
    for (let i = 0; i < gameState.board.length; i++) {
      if (gameState.board[i]?.state !== 'active') continue;
      for (let j = i + 1; j < gameState.board.length; j++) {
        if (gameState.board[j]?.state !== 'active') continue;
        const result = isValidPairFlat(gameState.board, i, j, 9);
        if (result.valid) {
          validPairs.push([i, j]);
        }
      }
    }

    const matchesLeft = validPairs.length;

    // Show popup toast when there are exactly 2 matches left (like HTML version)
    if (matchesLeft === 2 && gameState.stage > 2 && !lowMatchShown) {
      // Play toast sound for current language
      if (soundEnabled) {
        const toastSound = document.querySelector(`#toast-sound-${language}`);
        if (toastSound) {
          toastSound.play().catch(() => { });
        }
      }

      setUnlockToastMessage(t('unlock_toast_message').replace('{}', matchesLeft.toString()));
      setShowUnlockToast(true);
      setLowMatchShown(true);
      setTimeout(() => setShowUnlockToast(false), 2000);
    }

    // Reset flag when matches increase (new numbers added)
    if (matchesLeft > 2) {
      setLowMatchShown(false);
    }
  }, [gameState?.board, gameState?.stage, language, soundEnabled, t, lowMatchShown]);

  if (!gameState?.board) {
    return <div>Loading...</div>;
  }




  const handleCellClick = (index) => {
    if (!gameState.board[index] || gameState.board[index].state !== 'active') return;

    const result = selectCell(index);

    if (result?.error) {
      // Handle wrong match
      if (soundEnabled) sound.matchFail();
      setWrongPairCells([result.cell1, result.cell2]);

      // If there are blocking cells, show message
      if (result.blocking && result.blocking.length > 0) {
        setBlockingCells(result.blocking);
        setPathBlockedMessage(`Path blocked by ${result.blocking.length} cell${result.blocking.length > 1 ? 's' : ''}`);
        setShowPathBlocked(true);
      }

      setTimeout(() => {
        setWrongPairCells([]);
        setBlockingCells([]);
        setShowPathBlocked(false);
      }, 820);
    } else if (result?.cell1 !== undefined && result?.cell2 !== undefined) {
      // Handle successful match
      if (soundEnabled) sound.matchSuccess();

      // Draw match line with match type
      console.log('About to draw match line for cells:', result.cell1, result.cell2);
      drawMatchLine(result.cell1, result.cell2, result.matchType);

      // Small confetti for individual matches
      setConfettiCells([result.cell1, result.cell2]);
      setTimeout(() => setConfettiCells([]), 1000);

      // Process the match
      processMatch(result.cell1, result.cell2);
    }
  };

  const drawMatchLine = (index1, index2, matchType = 'direct') => {
    const gridContainer = document.querySelector('#main-game-grid');
    if (!gridContainer) return;

    const cells = gridContainer.querySelectorAll('div');
    const cell1 = cells[index1];
    const cell2 = cells[index2];
    if (!cell1 || !cell2) return;

    const appWrapper = document.querySelector('.w-full.h-full.bg-blue-50');
    if (!appWrapper) return;

    const appRect = appWrapper.getBoundingClientRect();
    const cell1Rect = cell1.getBoundingClientRect();
    const cell2Rect = cell2.getBoundingClientRect();

    const x1 = cell1Rect.left - appRect.left + cell1Rect.width / 2;
    const y1 = cell1Rect.top - appRect.top + cell1Rect.height / 2;
    const x2 = cell2Rect.left - appRect.left + cell2Rect.width / 2;
    const y2 = cell2Rect.top - appRect.top + cell2Rect.height / 2;

    if (matchType === 'sequential') {
      const gridRect = gridContainer.getBoundingClientRect();
      const firstIndex = Math.min(index1, index2);
      const secondIndex = Math.max(index1, index2);
      const firstCell = cells[firstIndex];
      const secondCell = cells[secondIndex];
      const rect1_ordered = firstCell.getBoundingClientRect();
      const rect2_ordered = secondCell.getBoundingClientRect();

      const lines = [
        {
          x1: rect1_ordered.left - appRect.left + rect1_ordered.width / 2,
          y1: rect1_ordered.top - appRect.top + rect1_ordered.height / 2,
          x2: gridRect.right - appRect.left,
          y2: rect1_ordered.top - appRect.top + rect1_ordered.height / 2
        },
        {
          x1: gridRect.left - appRect.left,
          y1: rect2_ordered.top - appRect.top + rect2_ordered.height / 2,
          x2: rect2_ordered.left - appRect.left + rect2_ordered.width / 2,
          y2: rect2_ordered.top - appRect.top + rect2_ordered.height / 2
        }
      ];
      setMatchLines(lines);
    } else {
      setMatchLines([{ x1, y1, x2, y2 }]);
    }

    setTimeout(() => {
      setMatchLines([]);
    }, 400);
  };

  const handleAddNumbers = () => {
    const validMovesExist = hasValidMovesFlat(gameState.board, 9);

    // Allow adding only when no valid moves exist and stage not cleared
    if (gameState.addRowsLeft <= 0 || validMovesExist || gameState.board.every(cell => cell.state !== 'active')) {
      return;
    }

    if (soundEnabled) sound.click();

    addRow();
  };

  const handleHint = () => {
    if (soundEnabled) sound.click();
    console.log('Hint clicked, hints left:', gameState?.hintsLeft);

    // Hide hint tooltip when hint is used
    setShowHintTooltip(false);
    if (handAnimationInterval.current) {
      clearInterval(handAnimationInterval.current);
    }

    if (gameState?.hintsLeft <= 0) {
      console.log('No hints left, returning');
      return;
    }

    const hintPair = getHint();
    console.log('Hint pair:', hintPair);
    if (hintPair) {
      setTimeout(() => clearSelection(), 3000);
    }
  };

  const getCellClass = (cell, index) => {
    let baseClass = "grid-cell flex items-center justify-center font-bold cursor-pointer transition-all duration-200 relative bg-white text-gray-800";

    if (cell.state === 'cleared') {
      return baseClass + " !bg-transparent !text-transparent cursor-default";
    }

    if (cell.state === 'blurred') {
      return baseClass + " !bg-gray-100 !text-gray-400 cursor-default";
    }

    if (selectedCellIndex === index) {
      return baseClass + " !bg-blue-500 !text-white";
    }

    if (hintHighlights.includes(index)) {
      return baseClass + " !bg-yellow-300 !text-gray-800";
    }

    if (wrongPairCells.includes(index) || blockingCells.includes(index)) {
      return baseClass + " shake";
    }

    return baseClass + " hover:bg-blue-50 active:bg-blue-100";
  };

  return (
    <div className="w-full h-full bg-blue-50 p-2 rounded-3xl shadow-2xl flex flex-col relative">
      {/* Hand Icon for Hint Tooltip */}
      {showHintTooltip && (
        <div
          className={`hand-icon ${isHandTapping ? 'tapping' : ''}`}
          style={{
            top: `${handPosition.top}px`,
            left: `${handPosition.left}px`
          }}
        >
          👆
        </div>
      )}

      {/* Audio elements for hint sounds */}
      <audio id="hint-sound-kn" src="https://raw.githubusercontent.com/sneha-xorstack/teluskoTraining/master/kannada%20hint.mp3" preload="auto" />
      <audio id="hint-sound-ta" src="https://raw.githubusercontent.com/sneha-xorstack/teluskoTraining/master/Tamil%20Hint.mp3" preload="auto" />
      <audio id="hint-sound-te" src="https://raw.githubusercontent.com/sneha-xorstack/teluskoTraining/master/Telugu%20hint.mp3" preload="auto" />
      <audio id="hint-sound-ml" src="https://raw.githubusercontent.com/sneha-xorstack/teluskoTraining/master/malayalam_hint.mp3" preload="auto" />
      <audio id="hint-sound-mr" src="https://raw.githubusercontent.com/sneha-xorstack/teluskoTraining/master/marathi_hint.mp3" preload="auto" />

      {/* Audio elements for toast sounds */}
      <audio id="toast-sound-en" src="https://raw.githubusercontent.com/sneha-xorstack/teluskoTraining/master/English%20Toast.mp3" preload="auto" />
      <audio id="toast-sound-hi" src="https://raw.githubusercontent.com/sneha-xorstack/teluskoTraining/master/Hindi%20Toast.mp3" preload="auto" />
      <audio id="toast-sound-kn" src="https://raw.githubusercontent.com/sneha-xorstack/teluskoTraining/master/kannada%20Toast.mp3" preload="auto" />
      <audio id="toast-sound-ta" src="https://raw.githubusercontent.com/sneha-xorstack/teluskoTraining/master/Tamil%20Toast.mp3" preload="auto" />
      <audio id="toast-sound-te" src="https://raw.githubusercontent.com/sneha-xorstack/teluskoTraining/master/Telugu%20Toast.mp3" preload="auto" />
      <audio id="toast-sound-ml" src="https://raw.githubusercontent.com/sneha-xorstack/teluskoTraining/master/malayalam_toast.mp3" preload="auto" />
      <audio id="toast-sound-mr" src="https://raw.githubusercontent.com/sneha-xorstack/teluskoTraining/master/marathi_toast.mp3" preload="auto" />

      {/* Effect Canvas */}
      <canvas ref={effectCanvasRef} className="absolute top-0 left-0 pointer-events-none z-40" />

      {/* SVG Line Overlay */}
      <svg
        id="line-svg-overlay"
        className="absolute top-0 left-0 w-full h-full pointer-events-none"
        style={{ zIndex: 41 }}
      >
        {matchLines.map((line, i) => (
          <line
            key={i}
            x1={line.x1}
            y1={line.y1}
            x2={line.x2}
            y2={line.y2}
            stroke="#3b82f6"
            strokeWidth="3"
            strokeLinecap="round"
          />
        ))}
      </svg>



      {/* Header */}
      <header className="relative flex items-center mb-1 px-2 flex-shrink-0">
        <button
          onClick={onHome}
          className="text-blue-600 w-10 h-10 flex items-center justify-center rounded-lg hover:bg-blue-100"
        >
          🏠
        </button>
        <h2 className="absolute left-1/2 transform -translate-x-1/2 text-xl font-bold text-blue-800">
          {t('stage')} {gameState.stage}
        </h2>
        <div className="flex items-center gap-2 ml-auto">
          <button
            onClick={() => setShowPauseModal(true)}
            className="text-blue-600 text-2xl w-10 h-10 flex items-center justify-center rounded-lg hover:bg-blue-100"
          >
            ⏸️
          </button>
          <div className="lang-dropdown">
            <button
              onClick={() => setShowLangDropdown(!showLangDropdown)}
              className="text-sm font-bold text-purple-700 p-2 rounded-lg bg-purple-100 hover:bg-purple-200 w-8 h-8 flex items-center justify-center"
            >
              {language === 'hi' ? 'हि' : language === 'kn' ? 'ಕ' : language === 'ta' ? 'த' : language === 'te' ? 'తె' : language === 'ml' ? 'മ' : language === 'mr' ? 'म' : 'EN'}
            </button>
            <div className={`lang-dropdown-content ${showLangDropdown ? 'show' : ''}`}>
              {languages.map(lang => (
                <a
                  key={lang.code}
                  href="#"
                  onClick={(e) => {
                    e.preventDefault();
                    setLanguage(lang.code);
                    setShowLangDropdown(false);
                  }}
                >
                  {lang.name}
                </a>
              ))}
            </div>
          </div>
        </div>
      </header>

      {/* Score Cards */}
      <div className="grid grid-cols-2 gap-4 mb-1 flex-shrink-0">
        <div className="score-card p-2 sm:p-3 rounded-xl text-center shadow">
          <p className="text-xs sm:text-sm text-gray-500 flex items-center justify-center gap-1">
            <span>⭐</span>{t('score')}
          </p>
          <p className="text-lg sm:text-2xl font-bold text-gray-800">{gameState.score}</p>
        </div>
        <div className="score-card p-2 sm:p-3 rounded-xl text-center shadow">
          <p className="text-xs sm:text-sm text-gray-500 flex items-center justify-center gap-1">
            <span>👑</span>{t('best')}
          </p>
          <p className="text-lg sm:text-2xl font-bold text-gray-800">{bestScore}</p>
        </div>
      </div>

      {/* Game Grid */}
      <div className="bg-white rounded-lg relative overflow-hidden flex-grow">
        <div id="main-game-grid" className="grid grid-cols-9" style={{
          borderLeft: '1px solid #e0e7ff',
          borderTop: '1px solid #e0e7ff',
          height: '100%'
        }}>
          {gameState.board.map((cell, index) => (
            <div
              key={index}
              onClick={() => handleCellClick(index)}
              className={`
                flex items-center justify-center cursor-pointer
                transition-all duration-200 relative
                ${cell.state === 'cleared'
                  ? 'bg-white'
                  : cell.state === 'blurred'
                    ? 'bg-gray-100 text-gray-400 cursor-default'
                    : selectedCellIndex === index || cell.tempSelected
                      ? 'bg-blue-500 text-white'
                      : hintHighlights.includes(index)
                        ? 'bg-yellow-300 text-gray-800'
                        : (wrongPairCells.includes(index) || blockingCells.includes(index))
                          ? 'bg-white text-gray-800 shake'
                          : 'bg-white text-gray-800 hover:bg-blue-50 active:bg-blue-100 active:scale-95'
                }
              `}
              style={{
                aspectRatio: '1 / 1',
                borderRight: '1px solid #e0e7ff',
                borderBottom: '1px solid #e0e7ff',
                fontSize: '1.5rem'
              }}
            >
              {cell?.value || ''}
              {(wrongPairCells.includes(index) || blockingCells.includes(index)) && (
                <div className="absolute inset-0 flex items-center justify-center text-red-500 text-3xl font-bold pointer-events-none wrong-pair-cross">
                  ✕
                </div>
              )}
              {confettiCells.includes(index) && (
                <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 pointer-events-none">
                  <ConfettiExplosion
                    particleCount={15}
                    width={200}
                    duration={1500}
                    force={0.3}
                    colors={['#f43f5e', '#3b82f6', '#10b981', '#f59e0b']}
                  />
                </div>
              )}

            </div>
          ))}
        </div>

        {/* Goal Notification */}
        {showGoalNotification && (
          <div className="absolute top-1/3 left-1/2 transform -translate-x-1/2 -translate-y-1/2 bg-blue-100 border-2 border-blue-300 text-blue-800 px-6 py-3 rounded-lg font-semibold text-sm z-50 shadow-lg whitespace-nowrap">
            {t('objective_toast')}
          </div>
        )}

        {/* Unlock Toast - matches HTML version unlock-toast */}
        <div
          className="fixed top-2/5 left-1/2 transform -translate-x-1/2 -translate-y-1/2 px-6 py-3 rounded-xl bg-blue-100 text-blue-600 font-bold z-60 pointer-events-none transition-opacity duration-500"
          style={{ opacity: showUnlockToast ? 1 : 0 }}
        >
          {unlockToastMessage || t('unlock_toast_message').replace('{}', '2')}
        </div>

        {/* Toast Notification - matches Ezygamers.html slide-in-toast */}
        <div
          className="absolute bottom-5 bg-gray-800 bg-opacity-90 text-white text-center px-3 py-3 rounded-lg text-sm transition-all duration-500 ease-in-out"
          style={{
            left: showToast ? '5%' : '-110%',
            width: '90%',
            marginLeft: '5%',
            marginRight: '5%',
            zIndex: 45
          }}
        >
          {toastMessage}
        </div>

        {/* Path Blocked Message */}
        {showPathBlocked && (
          <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 bg-red-100 border-2 border-red-300 text-red-800 px-4 py-2 rounded-lg font-semibold text-sm z-50 shadow-lg">
            {pathBlockedMessage}
          </div>
        )}
      </div>

      {/* Controls */}
      <footer className="py-1 flex-shrink-0 pb-6">
        <div className="flex flex-col items-center gap-1">
          <div className="flex items-start justify-around w-full gap-4 sm:gap-8">
            {/* WhatsApp Share */}
            <div className="relative">
              <button
                onClick={() => {
                  const shareText = `🧠 I just scored ${gameState.score} points on Stage ${gameState.stage} in SumLink! 🎯\n\nCan you beat my score? 🏆\n\nPlay now: https://play.ezygamers.com`;
                  const shareUrl = `https://wa.me/?text=${encodeURIComponent(shareText)}`;
                  window.open(shareUrl, '_blank');
                }}
                className="control-button bg-green-500 text-white flex items-center justify-center p-4"
              >
                <svg xmlns="http://www.w3.org/2000/svg" width="100%" height="100%" fill="currentColor" viewBox="0 0 16 16">
                  <path d="M13.601 2.326A7.854 7.854 0 0 0 7.994 0C3.627 0 .068 3.558.064 7.926c0 1.399.366 2.76 1.057 3.965L0 16l4.204-1.102a7.933 7.933 0 0 0 3.79.965h.004c4.368 0 7.926-3.558 7.93-7.93A7.898 7.898 0 0 0 13.6 2.326zM7.994 14.521a6.573 6.573 0 0 1-3.356-.92l-.24-.144-2.494.654.666-2.433-.156-.251a6.56 6.56 0 0 1-1.007-3.505c0-3.626 2.957-6.584 6.591-6.584a6.56 6.56 0 0 1 4.66 1.931 6.557 6.557 0 0 1 1.928 4.66c-.004 3.639-2.961 6.592-6.592 6.592zm3.615-4.934c-.197-.099-1.17-.578-1.353-.646-.182-.065-.315-.099-.445.099-.133.197-.513.646-.627.775-.114.133-.232.148-.43.05-.197-.1-.836-.308-1.592-.985-.59-.525-.985-1.175-1.103-1.372-.114-.198-.011-.304.088-.403.087-.088.197-.232.296-.346.1-.114.133-.198.198-.33.065-.134.034-.248-.015-.347-.05-.099-.445-1.076-.612-1.47-.16-.389-.323-.335-.445-.34-.114-.007-.247-.007-.38-.007a.729.729 0 0 0-.529.247c-.182.198-.691.677-.691 1.654 0 .977.71 1.916.81 2.049.098.133 1.394 2.132 3.383 2.992.47.205.84.326 1.129.418.475.152.904.129 1.246.08.38-.058 1.171-.48 1.338-.943.164-.464.164-.86.114-.943-.049-.084-.182-.133-.38-.232z" />
                </svg>
              </button>
            </div>

            {/* Add Numbers */}
            <div className="relative flex flex-col items-center">
              <button
                id="add-row-btn"
                onClick={handleAddNumbers}
                className={`control-button text-white flex items-center justify-center text-4xl ${gameState.addRowsLeft <= 0 ? 'bg-gray-400 cursor-not-allowed opacity-70' :
                    (!hasValidMovesFlat(gameState.board, 9) && gameState.board.some(cell => cell.state === 'active')) ? 'bg-blue-500' : 'bg-gray-400 cursor-not-allowed opacity-70'
                  }`}
                disabled={gameState.addRowsLeft <= 0 || hasValidMovesFlat(gameState.board, 9) || gameState.board.every(cell => cell.state !== 'active')}
              >
                +
              </button>
              <div id="add-row-badge" className="badge bg-red-500 text-white text-xs font-bold rounded-full flex items-center justify-center">
                {gameState.addRowsLeft}
              </div>

              {/* Add Button Tooltip - shows only when no valid moves exist and stage not cleared */}
              {!hasValidMovesFlat(gameState.board, 9) && gameState.addRowsLeft > 0 && gameState.board.some(cell => cell.state === 'active') && (
                <div
                  className="absolute bg-gray-800 text-white rounded-xl text-sm z-50 shadow-lg flex items-center justify-center text-center"
                  style={{
                    bottom: '100%',
                    left: '50%',
                    transform: 'translateX(-50%)',
                    marginBottom: '25px',
                    width: '120px',
                    height: '120px',
                    padding: '12px',
                    whiteSpace: 'normal'
                  }}
                >
                  {t('add_numbers_blurb')}
                  <div className="absolute top-full left-1/2 transform -translate-x-1/2 border-4 border-transparent border-t-gray-800"></div>
                </div>
              )}

              <button id="feedback-btn" onClick={() => setShowFeedbackModal(true)} className="text-sm text-green-600 underline mt-2" data-lang="feedback">
                {t('feedback')}
              </button>
              {/* Feedback Modal */}
              <FeedbackModal
                show={showFeedbackModal}
                onClose={() => setShowFeedbackModal(false)}
                language="en"
              />
            </div>

            {/* Hint */}
            <div className="relative">
              <button
                id="hint-btn"
                onClick={handleHint}
                className={`control-button flex items-center justify-center ${gameState.hintsLeft <= 0
                    ? 'bg-gray-400 cursor-not-allowed opacity-70'
                    : 'bg-yellow-400'
                  } text-white`}
                disabled={gameState.hintsLeft <= 0}
              >
                💡
              </button>
              <div id="hint-badge" className="badge bg-red-500 text-white text-xs font-bold rounded-full flex items-center justify-center">
                {gameState.hintsLeft}
              </div>
              {/* Hint Tooltip - matches Ezygamers.html hint-blurb styling */}
              {showHintTooltip && (
                <div
                  className="absolute bg-gray-800 text-white rounded-xl text-sm z-50 shadow-lg flex items-center justify-center text-center"
                  style={{
                    bottom: '100%',
                    left: '50%',
                    transform: 'translateX(-50%)',
                    marginBottom: '25px',
                    width: '120px',
                    height: '120px',
                    padding: '12px',
                    whiteSpace: 'normal'
                  }}
                >
                  {t('hint_blurb') || 'Show a Hint'}
                  <div className="absolute top-full left-1/2 transform -translate-x-1/2 border-4 border-transparent border-t-gray-800"></div>
                </div>
              )}
            </div>
          </div>
        </div>
      </footer>



      {/* Win Modal */}
      {showWin && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex flex-col items-center justify-center z-50">
          {/* Confetti Animation */}
          <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 z-60">
            <ConfettiExplosion
              particleCount={150}
              width={1800}
              duration={2000}
              force={0.2}
              colors={['#f43f5e', '#3b82f6', '#10b981', '#f59e0b', '#8b5cf6', '#ef4444']}
            />
          </div>
          <div className="text-center text-white relative z-70">
            <h2 className="text-4xl font-bold animate-bounce mb-4">{t('win_stage_cleared')}</h2>
          </div>
        </div>
      )}

      {/* Stage Start Modal */}
      {showStageStartModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="text-center text-white">
            <h2 className="text-4xl font-bold animate-bounce whitespace-pre-line">
              {stageStartMessage}
            </h2>
          </div>
        </div>
      )}

      {/* Pause Modal */}
      {showPauseModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white w-full max-w-xs p-6 rounded-2xl shadow-xl text-center relative">
            <button
              onClick={() => setShowPauseModal(false)}
              className="absolute top-2 right-2 text-2xl text-gray-400 hover:text-gray-600"
            >
              ×
            </button>
            <h3 className="text-2xl font-bold mb-4">{t('paused') || 'Paused'}</h3>
            <button
              onClick={() => {
                setShowPauseModal(false);
                if (onTutorial) onTutorial();
              }}
              className="w-full bg-blue-500 text-white font-bold py-3 rounded-xl mb-3 hover:bg-blue-600"
            >
              {t('how_to_play')}
            </button>
            <div className="flex flex-col gap-3">
              <button
                onClick={() => {
                  setShowPauseModal(false);
                  retryCurrentGame();
                }}
                className="w-full bg-gray-300 text-gray-800 font-bold py-3 rounded-xl hover:bg-gray-400"
              >
                {t('retry')}
              </button>
              <button
                onClick={() => setShowPauseModal(false)}
                className="w-full bg-blue-500 text-white font-bold py-3 rounded-xl hover:bg-blue-600"
              >
                {t('continue') || 'Continue'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Game Over Modal */}
      {showGameOver && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white w-full max-w-sm p-6 rounded-2xl shadow-xl text-center">
            <h3 className="text-2xl font-bold mb-6">{t('game_over_title')}</h3>
            <div className="flex justify-center gap-4">
              <button
                onClick={() => { goHome(); onHome(); }}
                className="bg-gray-300 text-gray-800 font-bold py-3 px-6 rounded-xl hover:bg-gray-400"
              >
                {t('home')}
              </button>
              <button
                onClick={retryStage}
                className="bg-blue-500 text-white font-bold py-3 px-6 rounded-xl hover:bg-blue-600"
              >
                {t('try_again')}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default GameBoard;