import React, { useState, useEffect, useRef } from 'react';
import ConfettiExplosion from 'react-confetti-explosion';
import { translations } from '../config/translations';
import { isValidPairFlat } from '../utils/gameLogic';
import { useLanguage } from '../App';

const languages = [
  { code: 'en', name: 'English' },
  { code: 'hi', name: 'हिन्दी' },
  { code: 'kn', name: 'ಕನ್ನಡ' },
  { code: 'ta', name: 'தமிழ்' },
  { code: 'te', name: 'తెలుగు' },
  { code: 'ml', name: 'മലയാളം' },
  { code: 'mr', name: 'मराठी' }
];

function TutorialScreen({ onComplete, playSound, hasGameState = false, onSkipTutorial }) {
  const { language, setLanguage } = useLanguage();
  const [tutorialBoard, setTutorialBoard] = useState([]);
  const [tutorialStep, setTutorialStep] = useState(0);
  const [selectedCell, setSelectedCell] = useState(null);
  const [showLangDropdown, setShowLangDropdown] = useState(false);
  const [showSpotlight, setShowSpotlight] = useState(false);
  const [showFirstOverlay, setShowFirstOverlay] = useState(false);
  const [showSecondOverlay, setShowSecondOverlay] = useState(false);
  const [tutorialPlayable, setTutorialPlayable] = useState(false);
  const [hintedPair, setHintedPair] = useState(null);
  const [showHandIcon, setShowHandIcon] = useState(false);
  const [handPosition, setHandPosition] = useState({ top: 0, left: 0 });
  const [handIcon, setHandIcon] = useState('👆');
  const [isHandTapping, setIsHandTapping] = useState(false);
  const [lineCoords, setLineCoords] = useState(null);
  const [matchLineCoords, setMatchLineCoords] = useState(null);
  const [showMatchConfetti, setShowMatchConfetti] = useState(false);
  const [hintUsed, setHintUsed] = useState(false);
  
  const gridRef = useRef(null);
  const addBtnRef = useRef(null);
  const hintBtnRef = useRef(null);
  const gridHandAnimationInterval = useRef(null);
  const buttonHandAnimationInterval = useRef(null);
  const spotlightTimer = useRef(null);

  const tutorialSequence = [
    { highlight: [2, 7], tutorial: { titleKey: "tut_title_1", textKey: "tut_text_1", progress: "1/4" } },
    { highlight: [6, 8], tutorial: { titleKey: "tut_title_2", textKey: "tut_text_2", progress: "2/4" } },
    { highlight: [3, 11], tutorial: { titleKey: "tut_title_5", textKey: "tut_text_5", progress: "3/4" } },
    { highlight: [4, 5], tutorial: { titleKey: "tut_title_3", textKey: "tut_text_3", progress: "4/4" } },
    { action: 'prompt_add', tutorial: { titleKey: "tut_title_7", textKey: "tut_text_7", progress: "" } },
    { action: 'add_numbers', tutorial: { titleKey: "tut_title_8", textKey: "tut_text_8", progress: "" } },
    { action: 'complete', tutorial: { titleKey: "tut_title_8", textKey: "tut_text_8", progress: "" } }
  ];

  const initTutorial = () => {
    const initialValues = [1, 9, 5, 6, 8, 2, 3, 5, 7, 2, 3, 4, 6, 9, 1];
    const inactiveIndices = [0, 1, 9, 14];
    const board = initialValues.map((val, i) => ({ 
      value: val, 
      state: inactiveIndices.includes(i) ? 'blurred' : 'active' 
    }));
    setTutorialBoard(board);
    setTutorialStep(0);
    setSelectedCell(null);
    setTutorialPlayable(true);
    setHintedPair(null);
    setHintUsed(false);
    setTutorialPlayable(true);
    hideHandIcon();
  };

  const hideHandIcon = () => {
    if (gridHandAnimationInterval.current) {
      clearInterval(gridHandAnimationInterval.current);
      gridHandAnimationInterval.current = null;
    }
    if (buttonHandAnimationInterval.current) {
      clearInterval(buttonHandAnimationInterval.current);
      buttonHandAnimationInterval.current = null;
    }
    setShowHandIcon(false);
    setIsHandTapping(false);
  };

  const pointHandToButton = (buttonRef, position = 'above', icon = '👆') => {
    hideHandIcon();
    setHandIcon(icon);
    
    const point = () => {
      if (!buttonRef.current) return;
      const rect = buttonRef.current.getBoundingClientRect();
      const containerRect = document.querySelector('.w-full.bg-white.p-2').getBoundingClientRect();
      
      let top, left;
      left = rect.left - containerRect.left + (rect.width / 2) - 20;
      
      if (position === 'above') {
        top = rect.top - containerRect.top - 50;
      } else if (position === 'bottom') {
        top = rect.bottom - containerRect.top;
      } else {
        top = rect.top - containerRect.top + (rect.height / 2) - 20;
        left = rect.left - containerRect.left - 40;
      }
      
      setHandPosition({ top, left });
      setShowHandIcon(true);
      setIsHandTapping(true);
      
      setTimeout(() => setIsHandTapping(false), 500);
    };
    
    buttonHandAnimationInterval.current = setInterval(point, 1200);
    point();
  };

  const pointToCell = (index) => {
    if (!gridRef.current) return;
    const cells = gridRef.current.querySelectorAll('.grid-cell');
    const cell = cells[index];
    if (!cell) return;
    
    const rect = cell.getBoundingClientRect();
    const containerRect = document.querySelector('.w-full.bg-white.p-2').getBoundingClientRect();
    
    const top = rect.top - containerRect.top + (rect.height / 2) - 20;
    const left = rect.left - containerRect.left + (rect.width / 2) - 20;
    
    setHandPosition({ top, left });
    setHandIcon('👆');
    setShowHandIcon(true);
    setIsHandTapping(true);
    
    setTimeout(() => setIsHandTapping(false), 500);
  };

  const startInteractiveTutorialStep = (idx1, idx2) => {
    hideHandIcon();
    let currentIndex = 0;
    const targets = [idx1, idx2];

    const pointToNext = () => {
      pointToCell(targets[currentIndex]);
      currentIndex = (currentIndex + 1) % 2;
    };

    gridHandAnimationInterval.current = setInterval(pointToNext, 1200);
    pointToNext();
  };

  const stepData = tutorialStep < tutorialSequence.length ? tutorialSequence[tutorialStep].tutorial : {};
  const currentStepConfig = tutorialStep < tutorialSequence.length ? tutorialSequence[tutorialStep] : {};

  const isHighlighted = (index) => {
    if (!currentStepConfig.highlight) return false;
    return currentStepConfig.highlight.includes(index);
  };

  const isSelected = (index) => selectedCell === index || tutorialBoard[index]?.tempSelected;
  const isBlocked = (index) => tutorialBoard[index]?.state === 'blurred';
  const isHinted = (index) => hintedPair && hintedPair.includes(index);

  const drawLine = (fromIndex, toIndex) => {
    if (!gridRef.current) return;
    
    // Add small delay to ensure DOM is updated
    setTimeout(() => {
      const cells = gridRef.current.querySelectorAll('.grid-cell');
      const fromCell = cells[fromIndex];
      const toCell = cells[toIndex];
      if (!fromCell || !toCell) return;
      
      const containerRect = gridRef.current.getBoundingClientRect();
      const fromRect = fromCell.getBoundingClientRect();
      const toRect = toCell.getBoundingClientRect();
      
      // Special case for step 4 (indices 4,5) - horizontal line outside grid
      if (tutorialStep === 3 && ((fromIndex === 4 && toIndex === 5) || (fromIndex === 5 && toIndex === 4))) {
        const lineY = -15; // Above the grid container
        setLineCoords([{
          x1: fromRect.left - containerRect.left,
          y1: lineY,
          x2: toRect.right - containerRect.left,
          y2: lineY
        }]);
        return;
      }
      
      // Regular diagonal line for other steps
      let x1 = fromRect.left - containerRect.left + fromRect.width / 2;
      let y1 = fromRect.top - containerRect.top + fromRect.height / 2;
      let x2 = toRect.left - containerRect.left + toRect.width / 2;
      let y2 = toRect.top - containerRect.top + toRect.height / 2;
      
      setLineCoords([{ x1, y1, x2, y2 }]);
    }, 10);
  };

  const clearLine = () => {
    setLineCoords(null);
  };

  const drawMatchLine = (index1, index2, matchType = 'direct') => {
    console.log('Drawing match line between', index1, index2, 'type:', matchType);
    
    if (!gridRef.current) return;
    const cells = gridRef.current.querySelectorAll('.grid-cell');
    const cell1 = cells[index1];
    const cell2 = cells[index2];
    if (!cell1 || !cell2) return;
    
    const gridRect = gridRef.current.getBoundingClientRect();
    const cell1Rect = cell1.getBoundingClientRect();
    const cell2Rect = cell2.getBoundingClientRect();
    
    if (matchType === 'sequential') {
      // For sequential (edge-to-edge) matches, draw two lines:
      // 1. From first cell to right edge of grid
      // 2. From left edge of grid to second cell
      const firstIndex = Math.min(index1, index2);
      const secondIndex = Math.max(index1, index2);
      const firstCell = cells[firstIndex];
      const secondCell = cells[secondIndex];
      const rect1_ordered = firstCell.getBoundingClientRect();
      const rect2_ordered = secondCell.getBoundingClientRect();
      
      const lines = [
        { 
          x1: rect1_ordered.left - gridRect.left + rect1_ordered.width / 2, 
          y1: rect1_ordered.top - gridRect.top + rect1_ordered.height / 2, 
          x2: gridRect.right - gridRect.left, 
          y2: rect1_ordered.top - gridRect.top + rect1_ordered.height / 2 
        },
        { 
          x1: gridRect.left - gridRect.left, 
          y1: rect2_ordered.top - gridRect.top + rect2_ordered.height / 2, 
          x2: rect2_ordered.left - gridRect.left + rect2_ordered.width / 2, 
          y2: rect2_ordered.top - gridRect.top + rect2_ordered.height / 2 
        }
      ];
      setMatchLineCoords(lines);
    } else {
      // Regular direct line for other match types
      const x1 = cell1Rect.left - gridRect.left + cell1Rect.width / 2;
      const y1 = cell1Rect.top - gridRect.top + cell1Rect.height / 2;
      const x2 = cell2Rect.left - gridRect.left + cell2Rect.width / 2;
      const y2 = cell2Rect.top - gridRect.top + cell2Rect.height / 2;
      
      setMatchLineCoords([{ x1, y1, x2, y2 }]);
    }
    
    setTimeout(() => {
      setMatchLineCoords(null);
    }, 400);
  };

  const handleCellClick = (index) => {
    if (!tutorialPlayable || tutorialBoard[index]?.state !== 'active') return;
    
    if (selectedCell === null) {
      setSelectedCell(index);
      // Point to the other cell in the pair only if hint hasn't been used
      if (!hintUsed) {
        const step = tutorialSequence[tutorialStep];
        if (step?.highlight) {
          const otherIndex = step.highlight.find(i => i !== index);
          if (otherIndex !== undefined) {
            hideHandIcon();
            setTimeout(() => pointToCell(otherIndex), 500);
          }
        }
      }
    } else {
      if (selectedCell === index) {
        setSelectedCell(null);
        clearLine();
        return;
      }

      hideHandIcon();
      
      const matchResult = isValidPairFlat(tutorialBoard, selectedCell, index, 5);
      if (matchResult.valid) {
        console.log('About to draw tutorial match line for cells:', selectedCell, index, 'matchType:', matchResult.type);
        // Draw match line with the correct type (sequential for edge-to-edge matches)
        drawMatchLine(selectedCell, index, matchResult.type);
        playSound?.matchSuccess();
        
        // Show both cells as selected (blue) during match
        const tempBoard = [...tutorialBoard];
        tempBoard[selectedCell] = { ...tempBoard[selectedCell], tempSelected: true };
        tempBoard[index] = { ...tempBoard[index], tempSelected: true };
        setTutorialBoard(tempBoard);
        
        // Show small confetti for match
        setShowMatchConfetti(true);
        setTimeout(() => setShowMatchConfetti(false), 1000);
        
        setTimeout(() => {
          const newBoard = [...tutorialBoard];
          newBoard[selectedCell].state = 'blurred';
          newBoard[index].state = 'blurred';
          delete newBoard[selectedCell].tempSelected;
          delete newBoard[index].tempSelected;
          setTutorialBoard(newBoard);
          setSelectedCell(null);
          setHintedPair(null);
          
          // Keep grid always playable
          setTutorialPlayable(true);
          
          clearLine();
          
          // Check if all active numbers are cleared
          const hasActiveNumbers = newBoard.some(c => c.state === 'active');
          if (tutorialStep === 5 && !hasActiveNumbers) {
            setTimeout(() => {
              handleTutorialComplete();
            }, 1000);
          } else {
            setTimeout(() => {
              if (tutorialStep < 4) {
                setTutorialStep(prev => prev + 1);
              }
            }, 500);
          }
        }, 300);
      } else {
        playSound?.matchFail();
        setTimeout(() => {
          setSelectedCell(null);
          setHintedPair(null);
          clearLine();
        }, 500);
      }
    }
  };

  const handleAddClick = () => {
    if (spotlightTimer.current) {
      clearTimeout(spotlightTimer.current);
      spotlightTimer.current = null;
    }
    setShowSpotlight(false);
    hideHandIcon();
    playSound?.click();
    
    // Add numbers first, then move to next step
    const newNumbers = [9, 3, 6];
    let lastNumberIndex = -1;
    for(let i = tutorialBoard.length - 1; i >= 0; i--) {
      if (tutorialBoard[i].state !== 'cleared') {
        lastNumberIndex = i;
        break;
      }
    }
    let insertIndex = lastNumberIndex + 1;
    const newBoard = [...tutorialBoard];
    newNumbers.forEach(num => {
      if(insertIndex < newBoard.length) {
        newBoard[insertIndex] = { value: num, state: 'active' };
        insertIndex++;
      }
    });
    setTutorialBoard(newBoard);
    
    setTimeout(() => {
      setTutorialStep(prev => prev + 1);
    }, 500);
  };

  const handleHintClick = () => {
    if (spotlightTimer.current) {
      clearTimeout(spotlightTimer.current);
      spotlightTimer.current = null;
    }
    setShowSpotlight(false);
    hideHandIcon();
    setHintUsed(true);
    playSound?.click();
    
    const pair = findValidPair();
    if (pair) {
      setHintedPair(pair);
      setTimeout(() => {
        setHintedPair(null);
      }, 3000);
    }
    
    // Grid remains playable - no need to enable/disable
  };

  const handleTutorialComplete = () => {
    localStorage.setItem('tutorialCompleted', 'true');
    setShowFirstOverlay(true);
    playSound?.win();
    
    setTimeout(() => {
      setShowFirstOverlay(false);
      setShowSecondOverlay(true);
      
      setTimeout(() => {
        setShowSecondOverlay(false);
        onComplete();
      }, 1500);
    }, 2000);
  };

  const handleActivity = () => {
    if (spotlightTimer.current) {
      clearTimeout(spotlightTimer.current);
      spotlightTimer.current = null;
    }
    setShowSpotlight(false);
  };

  const runTutorialStep = () => {
    if (tutorialStep >= tutorialSequence.length) return;
    
    const step = tutorialSequence[tutorialStep];
    
    if (step.highlight) {
      startInteractiveTutorialStep(step.highlight[0], step.highlight[1]);
      
      // Grid is always playable
      setTutorialPlayable(true);
      
    } else if (step.action) {
      handleTutorialAction(step.action);
    }
  };

  const handleTutorialAction = (action) => {
    if (action === 'prompt_add') {
      // Compact the board
      const newBoard = [];
      for (let i = 0; i < tutorialBoard.length; i += 5) {
        const row = tutorialBoard.slice(i, i + 5);
        if (!row.every(cell => cell.state === 'blurred' || cell.state === 'cleared')) {
          newBoard.push(...row);
        }
      }
      const compactedBoard = Array(15).fill({value: null, state: 'cleared'});
      newBoard.forEach((cell, i) => {
        compactedBoard[i] = cell;
      });
      setTutorialBoard(compactedBoard);
      
      // Point to add button
      setTimeout(() => {
        pointHandToButton(addBtnRef, 'above', '👇');
      }, 2000);
      
      // Start timer to show spotlight if idle
      spotlightTimer.current = setTimeout(() => {
        setShowSpotlight(true);
      }, 10000);
      

      
    } else if (action === 'add_numbers') {
      // Point to hint button and show spotlight
      setTimeout(() => {
        pointHandToButton(hintBtnRef, 'above', '👇');
      }, 1000);
      
      // Start timer to show spotlight if idle
      spotlightTimer.current = setTimeout(() => {
        setShowSpotlight(true);
      }, 5000);
      
    } else if (action === 'complete') {
      // This step is handled in the match logic now
    }
  };

  const findValidPair = () => {
    const activeCells = [];
    tutorialBoard.forEach((cell, i) => {
      if (cell.state === 'active') activeCells.push(i);
    });
    
    for(let i=0; i<activeCells.length; i++) {
      for(let j=i+1; j<activeCells.length; j++) {
        if(isValidPairFlat(tutorialBoard, activeCells[i], activeCells[j], 5).valid) {
          return [activeCells[i], activeCells[j]];
        }
      }
    }
    return null;
  };

  useEffect(() => {
    initTutorial();
    runTutorialStep();
  }, []);

  useEffect(() => {
    if (tutorialStep > 0) {
      runTutorialStep();
    }
  }, [tutorialStep]);
  
  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (showLangDropdown && !event.target.closest('.lang-dropdown')) {
        setShowLangDropdown(false);
      }
    };
    
    document.addEventListener('click', handleClickOutside);
    return () => document.removeEventListener('click', handleClickOutside);
  }, [showLangDropdown]);
  


  // Get current step data with translations
  const getCurrentStepData = () => {
    if (tutorialStep >= tutorialSequence.length) return {};
    
    const step = tutorialSequence[tutorialStep];
    const tutorial = step.tutorial;
    
    const equations = {
      0: "5 = 5",
      1: "3 + 7 = 10", 
      2: "6 + 4 = 10",
      3: "8 + 2 = 10"
    };
    
    return {
      title: translations[language]?.[tutorial.titleKey] || translations['en'][tutorial.titleKey] || '',
      text: translations[language]?.[tutorial.textKey] || translations['en'][tutorial.textKey] || '',
      progress: tutorial.progress,
      equation: equations[tutorialStep] || "",
      showAddButton: step.action === 'prompt_add',
      showHintButton: step.action === 'add_numbers'
    };
  };

  const currentStepData = getCurrentStepData();

  return (
    <div className="w-full bg-white p-2 sm:p-4 rounded-2xl shadow-lg flex flex-col justify-center h-full relative" style={{ overflowY: 'scroll', scrollbarWidth: 'none', msOverflowStyle: 'none' }}>
      <style>{`
        .tutorial-selected-override {
          background-color: #3b82f6 !important;
          color: white !important;
        }
        @keyframes tap-animation {
          0%, 100% { transform: scale(1); }
          50% { transform: scale(0.85); }
        }
        .tapping {
          animation: tap-animation 0.5s ease-in-out;
        }
        .w-full.bg-white::-webkit-scrollbar {
          display: none;
        }
      `}</style>
      {/* Skip button for returning users with progress */}
      {hasGameState && (
        <button
          onClick={() => {
            if (onSkipTutorial) {
              onSkipTutorial();
            } else {
              // Fallback: go straight to game without resetting progress
              onComplete?.();
            }
          }}
          className="absolute top-2 left-2 z-50 text-sm font-semibold px-3 py-1 rounded-lg bg-gray-200 hover:bg-gray-300 text-gray-800"
        >
          Skip
        </button>
      )}

      {/* Hand Icon */}
      {showHandIcon && (
        <div 
          className={`hand-icon ${isHandTapping ? 'tapping' : ''} ${showSpotlight ? 'z-70' : 'z-50'}`}
          style={{
            top: `${handPosition.top}px`,
            left: `${handPosition.left}px`
          }}
        >
          {handIcon}
        </div>
      )}
      
      <div>
        <div className="flex justify-between items-start mb-8">
          <div className="w-8"></div>
          <div className="text-center">
            <h1 className="text-2xl font-bold text-gray-700 mb-4">{translations[language]?.how_to_play_title || 'Tutorial!'}</h1>
            {currentStepData.equation && (
              <p className="text-4xl font-semibold">{currentStepData.equation}</p>
            )}
          </div>
        <div className="lang-dropdown">
          <button 
            onClick={() => setShowLangDropdown(!showLangDropdown)}
            className="text-sm font-bold text-purple-700 p-1 rounded-lg bg-purple-100 hover:bg-purple-200 w-8 h-8 flex items-center justify-center"
          >
            {language === 'hi' ? 'हि' : language === 'kn' ? 'ಕ' : language === 'ta' ? 'த' : language === 'te' ? 'తె' : language === 'ml' ? 'മ' : language === 'mr' ? 'म' : 'EN'}
          </button>
          <div className={`lang-dropdown-content ${showLangDropdown ? 'show' : ''}`}>
            {languages.map(lang => (
              <a 
                key={lang.code}
                href="#" 
                onClick={(e) => { 
                  e.preventDefault(); 
                  setLanguage(lang.code);
                  setShowLangDropdown(false);
                }}
              >
                {lang.name}
              </a>
            ))}
          </div>
        </div>
      </div>

        <div 
          ref={gridRef}
          className="game-grid-container grid grid-cols-5 border-t border-l border-gray-200 rounded-lg overflow-hidden mb-4 relative" 
          onClick={handleActivity}
        >
        <svg 
          className="absolute top-0 left-0 w-full h-full pointer-events-none"
          style={{ zIndex: 41 }}
        >
          {lineCoords && (
            Array.isArray(lineCoords) ? (
              lineCoords.map((line, i) => (
                <line
                  key={i}
                  x1={line.x1}
                  y1={line.y1}
                  x2={line.x2}
                  y2={line.y2}
                  stroke="#3b82f6"
                  strokeWidth="3"
                  strokeLinecap="round"
                />
              ))
            ) : (
              <line
                x1={lineCoords.x1}
                y1={lineCoords.y1}
                x2={lineCoords.x2}
                y2={lineCoords.y2}
                stroke="#3b82f6"
                strokeWidth="3"
                strokeLinecap="round"
              />
            )
          )}
          {matchLineCoords && (
            Array.isArray(matchLineCoords) ? (
              matchLineCoords.map((line, i) => (
                <line
                  key={i}
                  x1={line.x1}
                  y1={line.y1}
                  x2={line.x2}
                  y2={line.y2}
                  stroke="#3b82f6"
                  strokeWidth="3"
                  strokeLinecap="round"
                />
              ))
            ) : (
              <line
                x1={matchLineCoords.x1}
                y1={matchLineCoords.y1}
                x2={matchLineCoords.x2}
                y2={matchLineCoords.y2}
                stroke="#3b82f6"
                strokeWidth="3"
                strokeLinecap="round"
              />
            )
          )}
        </svg>
        {/* Small Match Confetti */}
        {showMatchConfetti && (
          <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 z-50">
            <ConfettiExplosion 
              particleCount={30}
              width={600}
              duration={2000}
              force={0.15}
              colors={['#f43f5e', '#3b82f6', '#10b981', '#f59e0b']}
            />
          </div>
        )}
        {tutorialBoard.map((cell, index) => (
          <div
            key={index}
            onClick={() => handleCellClick(index)}
            className={`
              grid-cell flex items-center justify-center text-2xl sm:text-3xl
              ${cell.state === 'cleared'
                ? 'bg-white'
                : isBlocked(index)
                  ? 'blurred'
                  : isSelected(index)
                    ? 'selected tutorial-selected-override'
                    : isHinted(index)
                      ? 'hint-highlight'
                      : isHighlighted(index) 
                        ? 'tutorial-initial-highlight text-gray-800' 
                        : 'bg-white text-gray-800 hover:bg-gray-50'
              }
            `}
          >
            {cell.state !== 'cleared' ? cell.value : ''}
          </div>
        ))}
      </div>

        <div className="text-center">
          <h3 className="text-2xl sm:text-3xl font-bold text-blue-800 mb-2">
            {currentStepData.title || 'Find Pair Of Numbers'}
          </h3>
          <div className="mb-4">
            <p className="text-sm text-gray-700" dangerouslySetInnerHTML={{ __html: currentStepData.text }}></p>
            <div className="flex justify-center items-center mt-1">
              <span className="text-xs font-medium text-gray-500">
                {currentStepData.progress || '1/4'}
              </span>
            </div>
          </div>
        </div>
      </div>

      <div>
        <div className="w-full flex items-center justify-center gap-8 pt-12" onClick={handleActivity}>
          {currentStepData.showAddButton && (
            <div className={`relative text-center ${showSpotlight ? 'bg-white bg-opacity-20 rounded-full p-4' : ''}`} style={showSpotlight ? { zIndex: 60 } : {}}>
              <button 
                ref={addBtnRef}
                onClick={handleAddClick}
                className="control-button bg-blue-500 text-white flex items-center justify-center text-2xl sm:text-4xl mx-auto pumping"
              >
                +
              </button>
              <div className="absolute bottom-full left-1/2 transform -translate-x-1/2 mb-4 bg-gray-800 text-white rounded-full text-xs px-3 py-1 whitespace-nowrap">
                {translations[language]?.add_numbers_blurb || 'Add numbers to continue'}
              </div>
            </div>
          )}
          {currentStepData.showHintButton && (
            <div className={`relative text-center ${showSpotlight ? 'bg-white bg-opacity-20 rounded-full p-4' : ''}`} style={showSpotlight ? { zIndex: 60 } : {}}>
              <button 
                ref={hintBtnRef}
                onClick={handleHintClick}
                className="control-button bg-yellow-400 text-white flex items-center justify-center text-4xl pumping"
              >
                💡
              </button>
              <div className="absolute bottom-full left-1/2 transform -translate-x-1/2 mb-4 bg-gray-800 text-white rounded-full text-xs px-3 py-1 whitespace-nowrap">
                {translations[language]?.hint_blurb || 'Take a hint'}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Spotlight Overlay */}
      {showSpotlight && (
        <div className="absolute inset-0 bg-black z-50 flex items-center justify-center p-6">
          {/* Message Box */}
          <div className="w-11/12 max-w-sm bg-white border-2 border-blue-400 rounded-xl shadow-lg p-4 text-center">
            <p className="text-lg font-semibold text-gray-800">
              {currentStepData.showAddButton ? translations[language]?.tut_add_btn_text || 'Click on the + icon button to add more numbers' : translations[language]?.hint_blurb || 'Show a Hint'}
            </p>
          </div>
          
          {/* Click handler */}
          <div 
            className="absolute inset-0 -z-10"
            onClick={() => setShowSpotlight(false)}
          />
        </div>
      )}
      
      {/* Tutorial Completion Overlays */}
      {showFirstOverlay && (
        <div className="fixed inset-0 bg-black bg-opacity-80 z-50 flex items-center justify-center">
          <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 z-60">
            <ConfettiExplosion 
              particleCount={150}
              width={1800}
              duration={2000}
              force={0.2}
              colors={['#f43f5e', '#3b82f6', '#10b981', '#f59e0b', '#8b5cf6', '#ef4444']}
            />
          </div>
          <div className="text-center text-white relative z-70">
            <h2 className="text-4xl font-bold mb-4">{translations[language]?.tut_complete_title || 'Well Done!'}</h2>
            <p className="text-2xl">{translations[language]?.win_tutorial_complete || 'Tutorial Complete! 🎉'}</p>
          </div>
        </div>
      )}
      
      {showSecondOverlay && (
        <div className="fixed inset-0 bg-black bg-opacity-80 z-50 flex items-center justify-center">
          <div className="text-center text-white relative z-70">
            <h2 className="text-4xl font-bold mb-4">{translations[language]?.get_ready || 'Get Ready!'}</h2>
            <p className="text-2xl">{translations[language]?.stage || 'Stage'} 1</p>
          </div>
        </div>
      )}
    </div>
  );
}

export default TutorialScreen;