import React from 'react';
import { trackLanguageSelected } from '../utils/analytics';

const languages = [
  { code: 'en', name: 'English' },
  { code: 'hi', name: 'हिन्दी' },
  { code: 'kn', name: 'ಕನ್ನಡ' },
  { code: 'ta', name: 'தமிழ்' },
  { code: 'te', name: 'తెలుగు' },
  { code: 'ml', name: 'മലയാളം' },
  { code: 'mr', name: 'मराठी' }
];

function LanguageSelection({ onLanguageSelect }) {
  return (
    <div className="w-full h-full p-6 sm:p-8 rounded-3xl shadow-2xl text-center flex flex-col justify-center bg-blue-200">
      <h1 className="text-3xl sm:text-4xl font-bold text-blue-800 mb-8">
        Choose Your Language
      </h1>
      <div className="space-y-4">
        {languages.map((lang) => (
          <button
            key={lang.code}
            onClick={() => {
              trackLanguageSelected(lang.code);
              onLanguageSelect(lang.code);
            }}
            className="w-full bg-white text-gray-800 font-bold py-3 rounded-xl hover:bg-gray-200 transition-colors"
          >
            {lang.name}
          </button>
        ))}
      </div>
    </div>
  );
}

export default LanguageSelection;