import React, { useState } from 'react';
import { translations } from '../config/translations';
import { trackFeedbackOpen, trackFeedbackSubmit } from '../utils/analytics';

function FeedbackModal({ show, onClose, language = 'en' }) {
  const [rating, setRating] = useState(0);
  const [comment, setComment] = useState('');
  const [showThankYou, setShowThankYou] = useState(false);

  const t = (key) => translations[language]?.[key] || translations.en[key] || key;

  const handleSubmit = (e) => {
    e.preventDefault();
    if (rating === 0) return;

    trackFeedbackSubmit(rating, comment.length > 0);
    setShowThankYou(true);

    setTimeout(() => {
      setShowThankYou(false);
      onClose();
      setRating(0);
      setComment('');
    }, 3000);
  };

  if (!show) return null;

  if (showThankYou) {
    return (
      <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
        <div className="bg-white w-full max-w-xs p-8 rounded-2xl shadow-xl text-center relative">
          <div className="w-24 h-24 mx-auto mb-4 text-yellow-400 text-6xl">👍</div>
          <h3 className="text-2xl font-bold">{t('thank_you') || 'Thank you for the feedback!'}</h3>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white w-full max-w-sm p-6 rounded-2xl shadow-xl relative max-h-[90vh] overflow-y-auto mx-4">
        <button
          onClick={onClose}
          className="absolute top-2 right-2 text-2xl text-gray-400 hover:text-gray-600"
        >
          ×
        </button>

        <form onSubmit={handleSubmit} className="space-y-4 text-left">
          <div>
            <label className="font-semibold text-gray-700 block text-center mb-1">
              {t('form_rate_exp') || 'Rate Your Experience'}
            </label>
            <div className="flex justify-center gap-1">
              {[1, 2, 3, 4, 5].map((star) => (
                <button
                  key={star}
                  type="button"
                  onClick={() => setRating(star)}
                  className={`text-3xl ${rating >= star ? 'text-yellow-400' : 'text-gray-300'}`}
                >
                  ★
                </button>
              ))}
            </div>
          </div>

          <div>
            <textarea
              value={comment}
              onChange={(e) => setComment(e.target.value)}
              placeholder={t('form_placeholder') || 'Tell us what you think...'}
              className="w-full h-24 p-2 border rounded-md mt-1"
            />
          </div>

          <div className="flex justify-end gap-4">
            <button
              type="button"
              onClick={onClose}
              className="bg-gray-300 text-gray-800 font-bold py-2 px-4 rounded-xl hover:bg-gray-400"
            >
              {t('cancel') || 'Cancel'}
            </button>
            <button
              type="submit"
              disabled={rating === 0}
              className="bg-blue-500 text-white font-bold py-2 px-4 rounded-xl hover:bg-blue-600 disabled:bg-gray-400"
            >
              {t('submit') || 'Submit Feedback'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

export default FeedbackModal;