export const trackGameStart = (stage = 1) => {
  trackEvent('game_start', { stage });
};

export const trackGameComplete = (stage, score, time) => {
  trackEvent('level_complete', { stage, score, time });
};

export const trackGameOver = (stage, score, reason) => {
  trackEvent('game_over', { stage, score, reason });
};

export const trackHintUsed = (stage, hintsLeft) => {
  trackEvent('hint_used', { stage, hints_remaining: hintsLeft });
};

export const trackRowAdded = (stage, rowsLeft) => {
  trackEvent('row_added', { stage, rows_remaining: rowsLeft });
};

export const trackShare = (platform, score) => {
  trackEvent('share', { platform, score });
};

