import React, { useState } from 'react';
import useLocalStorage from '../hooks/useLocalStorage';
import { translations } from '../config/translations';
import { trackNewGameStart, trackContinueGame, trackSettingsOpen } from '../utils/analytics';
import { useLanguage } from '../App';

// Add CSS for selected language styling
const selectedLangStyle = `
  .selected-lang {
    background-color: #e9d5ff;
    border: 2px solid #9333ea;
    color: #6b21a8;
    font-weight: bold;
  }
`;

// Inject the CSS
if (typeof document !== 'undefined') {
  const styleElement = document.createElement('style');
  styleElement.textContent = selectedLangStyle;
  document.head.appendChild(styleElement);
}


function HomeScreen({ onNewGame, onContinue, onRetry, onTutorial, hasGameState, currentLanguage }) {
  const [bestScore] = useLocalStorage('bestScore', 0);
  const language = currentLanguage || 'en';
  const { setLanguage } = useLanguage();

  const [showNewGameModal, setShowNewGameModal] = useState(false);
  const [showSettingsModal, setShowSettingsModal] = useState(false);
  const [soundEnabled, setSoundEnabled] = useLocalStorage('soundEnabled', true);

  const handleLanguageChange = (langCode) => {
    setLanguage(langCode);
  };



  
  const t = (key) => translations[language]?.[key] || translations.en[key] || key;

  return (
    <div className="w-full h-full bg-blue-50 p-4 rounded-3xl shadow-2xl text-gray-800 relative overflow-hidden flex flex-col justify-center">
      {/* Action Buttons */}
      <div className="space-y-4">
        {hasGameState && (
          <button 
            onClick={() => {
              const gameState = JSON.parse(localStorage.getItem('gameState') || '{}');
              trackContinueGame(gameState.stage || 1);
              onContinue();
            }}
            className="w-full bg-blue-500 text-white font-bold py-3 rounded-xl hover:bg-blue-600"
          >
            {t('continue')}
          </button>
        )}

        {hasGameState && (
          <button 
            onClick={() => {
              onRetry();
            }}
            className="w-full bg-gray-300 text-gray-800 font-bold py-3 rounded-xl hover:bg-gray-400"
          >
            {t('retry')}
          </button>
        )}
        
        <button 
          onClick={() => {
            if (hasGameState) {
              setShowNewGameModal(true);
            } else {
              trackNewGameStart();
              onNewGame();
            }
          }}
          className="w-full text-white font-bold py-3 rounded-xl hover:opacity-90"
          style={{ backgroundColor: '#002387' }}
        >
          {t('new_game')}
        </button>
        
        <button 
          onClick={() => {
            trackSettingsOpen();
            setShowSettingsModal(true);
          }}
          className="w-full text-white font-bold py-3 rounded-xl hover:opacity-90"
          style={{ backgroundColor: '#8A9A5B' }}
        >
          {t('settings')}
        </button>
      </div>
      
      <div className="w-full bg-white text-gray-800 font-bold py-3 rounded-xl shadow text-center mt-4">
        {t('best')}: {bestScore}
      </div>
      
      {/* New Game Confirmation Modal */}
      {showNewGameModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white w-full max-w-sm p-6 rounded-2xl shadow-xl text-center relative mx-4">
            <h3 className="text-xl font-bold mb-4">{t('new_game_confirm_title')}</h3>
            <p className="text-gray-600 mb-6">{t('new_game_confirm_text')}</p>
            <div className="flex justify-center gap-4">
              <button 
                onClick={() => setShowNewGameModal(false)}
                className="bg-gray-300 text-gray-800 font-bold py-3 px-6 rounded-xl hover:bg-gray-400"
              >
                {t('no')}
              </button>
              <button 
                onClick={() => {
                  setShowNewGameModal(false);
                  trackNewGameStart();
                  onNewGame();
                }}
                className="bg-blue-500 text-white font-bold py-3 px-6 rounded-xl hover:bg-blue-600"
              >
                {t('yes')}
              </button>
            </div>
          </div>
        </div>
      )}
      
      {/* Settings Modal */}
      {showSettingsModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white w-full max-w-xs p-6 rounded-2xl shadow-xl text-center relative mx-4">
            <button 
              onClick={() => setShowSettingsModal(false)}
              className="absolute top-2 right-2 text-2xl text-gray-400 hover:text-gray-600"
            >
              ×
            </button>
            <h3 className="text-2xl font-bold mb-4">{t('settings')}</h3>
            <div className="mb-6">
              <h4 className="text-xl font-bold mb-2">{t('sound')}</h4>
              <button 
                onClick={() => setSoundEnabled(!soundEnabled)}
                className="bg-blue-100 text-blue-600 text-4xl p-4 rounded-xl hover:bg-blue-200 w-24"
              >
                {soundEnabled ? '🔊' : '🔇'}
              </button>
            </div>
            <div>
              <h4 className="text-xl font-bold mb-2">{t('language')}</h4>
              <div className="grid grid-cols-2 gap-3">
                <button 
                  onClick={() => handleLanguageChange('en')}
                  className={`text-lg p-2 rounded-md hover:bg-gray-200 ${
                    language === 'en' ? 'selected-lang' : ''
                  }`}
                >English</button>
                <button 
                  onClick={() => handleLanguageChange('hi')}
                  className={`text-lg p-2 rounded-md hover:bg-gray-200 ${
                    language === 'hi' ? 'selected-lang' : ''
                  }`}
                >हिन्दी</button>
                <button 
                  onClick={() => handleLanguageChange('kn')}
                  className={`text-lg p-2 rounded-md hover:bg-gray-200 ${
                    language === 'kn' ? 'selected-lang' : ''
                  }`}
                >ಕನ್ನಡ</button>
                <button 
                  onClick={() => handleLanguageChange('ta')}
                  className={`text-lg p-2 rounded-md hover:bg-gray-200 ${
                    language === 'ta' ? 'selected-lang' : ''
                  }`}
                >தமிழ்</button>
                <button 
                  onClick={() => handleLanguageChange('te')}
                  className={`text-lg p-2 rounded-md hover:bg-gray-200 ${
                    language === 'te' ? 'selected-lang' : ''
                  }`}
                >తెలుగు</button>
                <button 
                  onClick={() => handleLanguageChange('ml')}
                  className={`text-lg p-2 rounded-md hover:bg-gray-200 ${
                    language === 'ml' ? 'selected-lang' : ''
                  }`}
                >മലയാളം</button>
                <button 
                  onClick={() => handleLanguageChange('mr')}
                  className={`text-lg p-2 rounded-md hover:bg-gray-200 ${
                    language === 'mr' ? 'selected-lang' : ''
                  }`}
                >मराठी</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default HomeScreen;