import React, { useState, useEffect, createContext, useContext } from 'react';
import { BrowserRouter as Router, Routes, Route, useParams, useNavigate, Navigate } from 'react-router-dom';
import LanguageSelection from './components/LanguageSelection';
import HomeScreen from './components/HomeScreen';
import TutorialScreen from './components/TutorialScreen';
import GameBoard from './components/GameBoard';
import useLocalStorage from './hooks/useLocalStorage';
import useSound from './hooks/useSound';

// Global language context
const LanguageContext = createContext();
export const useLanguage = () => useContext(LanguageContext);

const languageMap = {
  'english': 'en',
  'hindi': 'hi', 
  'kannada': 'kn',
  'tamil': 'ta',
  'telugu': 'te',
  'malayalam': 'ml',
  'marathi': 'mr'
};

const reverseLanguageMap = {
  'en': 'english',
  'hi': 'hindi',
  'kn': 'kannada', 
  'ta': 'tamil',
  'te': 'telugu',
  'ml': 'malayalam',
  'mr': 'marathi'
};

function LanguageSelectionApp() {
  const navigate = useNavigate();
  const { matchSuccess, matchFail, win, click } = useSound();

  // Check if user has previously selected a language
  React.useEffect(() => {
    const savedLanguage = localStorage.getItem('gameLanguage');
    if (savedLanguage) {
      const urlLang = reverseLanguageMap[savedLanguage];
      if (urlLang) {
        navigate(`/${urlLang}`);
        return;
      }
    }
  }, [navigate]);

  const handleLanguageSelect = (selectedLang) => {
    const urlLang = reverseLanguageMap[selectedLang];
    localStorage.setItem('gameLanguage', selectedLang);
    // Set a flag to indicate this is a fresh language selection
    localStorage.setItem('freshLanguageSelection', 'true');
    navigate(`/${urlLang}`);
  };

  return (
    <LanguageContext.Provider value={{ language: null, setLanguage: null }}>
      <div className="flex items-center justify-center min-h-screen p-2 bg-game-blue">
        <div className="relative w-full h-screen sm:max-w-md mx-auto overflow-y-auto rounded-3xl flex items-center">
          <LanguageSelection onLanguageSelect={handleLanguageSelect} />
        </div>
      </div>
    </LanguageContext.Provider>
  );
}

function GameApp() {
  const { lang } = useParams();
  const navigate = useNavigate();
  const [gameState, setGameState] = useLocalStorage('gameState', null);
  const [currentScreen, setCurrentScreen] = useLocalStorage('currentScreen', 'language');
  const { matchSuccess, matchFail, win, click } = useSound();
  
  const language = languageMap[lang] || null;

  useEffect(() => {
    const savedLanguage = localStorage.getItem('gameLanguage');
    const freshLanguageSelection = localStorage.getItem('freshLanguageSelection');
    
    // Prioritize URL language over localStorage
    if (language) {
      // Update localStorage to match URL language
      localStorage.setItem('gameLanguage', language);
      
      if (freshLanguageSelection === 'true') {
        localStorage.removeItem('freshLanguageSelection');
        const tutorialCompleted = localStorage.getItem('tutorialCompleted');
        const hasGameState = localStorage.getItem('gameState');
        
        if (!tutorialCompleted && !hasGameState) {
          setCurrentScreen('tutorial');
        } else {
          setCurrentScreen('home');
        }
      }
      return;
    }
    
    // No valid language in URL
    if (!savedLanguage) {
      navigate('/');
      return;
    }
    
    // Redirect to saved language URL
    const urlLang = reverseLanguageMap[savedLanguage];
    if (urlLang) {
      navigate(`/${urlLang}`);
    }
  }, [language, lang, navigate, setCurrentScreen]);



  // Reset game state and progress
  const resetGameState = () => {
    setGameState(null);
    Object.keys(localStorage).forEach(key => {
      if (key.includes('gameState') || key.includes('bestScore') || key.includes('matchedCells_')) {
        localStorage.removeItem(key);
      }
    });
    window.location.reload();
  };

  // Reset tutorial completion status
  const resetTutorialStatus = () => {
    localStorage.removeItem('tutorialCompleted');
    window.location.reload();
  };

  // Expose reset functions globally for testing
  window.resetLanguage = () => {
    localStorage.removeItem('gameLanguage');
    setGameState(null);
    setCurrentScreen('language');
    navigate('/');
  };
  window.resetGame = resetGameState;
  window.resetTutorial = resetTutorialStatus;
  
  // Test functions for toast and audio
  window.testLowMatches = () => {
    // Test the unlock toast (popup)
    const event = new CustomEvent('testUnlockToast', {
      detail: { message: 'Low matches! Use hint or add row' }
    });
    window.dispatchEvent(event);
  };
  
  window.testToast = (message, type = 'success') => {
    if (type === 'warning') {
      const event = new CustomEvent('testUnlockToast', {
        detail: { message }
      });
      window.dispatchEvent(event);
    } else {
      const event = new CustomEvent('testSlideToast', {
        detail: { message }
      });
      window.dispatchEvent(event);
    }
  };
  
  window.testHintAudio = (text = 'Test hint message') => {
    const event = new CustomEvent('playHintAudio', {
      detail: { text, language }
    });
    window.dispatchEvent(event);
  };
  
  window.testAllToasts = () => {
    setTimeout(() => window.testToast('Match found!', 'success'), 0);
    setTimeout(() => window.testToast('Invalid move!', 'error'), 2000);
    setTimeout(() => window.testLowMatches(), 4000);
    setTimeout(() => window.testToast('Stage completed!', 'success'), 6000);
  };
  
  window.testSounds = () => {
    setTimeout(() => matchSuccess(), 0);
    setTimeout(() => matchFail(), 1000);
    setTimeout(() => win(), 2000);
    setTimeout(() => click(), 3000);
  };

  const handleLanguageSelect = (selectedLang) => {
    const urlLang = reverseLanguageMap[selectedLang];
    localStorage.setItem('gameLanguage', selectedLang);
    localStorage.setItem('freshLanguageSelection', 'true');
    navigate(`/${urlLang}`);
  };

  const handleNewGame = () => {
    setGameState(null);
    // Clear all matched cells for all stages
    Object.keys(localStorage).forEach(key => {
      if (key.startsWith('matchedCells_')) {
        localStorage.removeItem(key);
      }
    });
    setCurrentScreen('game');
  };

  const handleRetryCurrentGame = () => {
    setCurrentScreen('game');
    setTimeout(() => {
      window.dispatchEvent(new CustomEvent('retryFromHome'));
    }, 100);
  };

  const handleStageSelect = (stage) => {
    const newGameState = { ...gameState, stage };
    setGameState(newGameState);
    setCurrentScreen('game');
  };

  const handleTutorial = () => {
    setCurrentScreen('tutorial');
  };

  const renderScreen = () => {
    switch (currentScreen) {
      case 'language':
        return <LanguageSelection onLanguageSelect={handleLanguageSelect} />;
      case 'home':
        return <HomeScreen 
          onNewGame={handleNewGame}
          onContinue={() => setCurrentScreen('game')}
          onRetry={handleRetryCurrentGame}
          onTutorial={() => setCurrentScreen('tutorial')}
          hasGameState={!!gameState}
          currentLanguage={language}
        />;
      case 'tutorial':
        return <TutorialScreen 
          onComplete={() => {
            // Create initial game state for stage 1 after tutorial completion
            setGameState({ stage: 1 });
            setCurrentScreen('game');
          }} 
          playSound={{ matchSuccess, matchFail, win, click }}
          hasGameState={!!gameState}
          onSkipTutorial={() => setCurrentScreen('game')}
        />;
      case 'game':
        return <GameBoard 
          onHome={() => setCurrentScreen('home')} 
          onTutorial={handleTutorial}
          currentLanguage={language}
          onGameComplete={() => setCurrentScreen('home')}
        />;
      default:
        return <HomeScreen 
          onNewGame={handleNewGame}
          onContinue={() => setCurrentScreen('game')}
          onRetry={handleRetryCurrentGame}
          onTutorial={() => setCurrentScreen('tutorial')}
          hasGameState={!!gameState}
          currentLanguage={language}
        />;
    }
  };

  const setLanguage = (newLang) => {
    const urlLang = reverseLanguageMap[newLang];
    localStorage.setItem('gameLanguage', newLang);
    navigate(`/${urlLang}`);
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage }}>
      <div className="flex items-center justify-center min-h-screen p-2 bg-game-blue">
        <div className="relative w-full h-screen sm:max-w-md mx-auto overflow-y-auto rounded-3xl flex items-center">
          {renderScreen()}
        </div>
      </div>
    </LanguageContext.Provider>
  );
}

function App() {
  return (
    <Router>
      <Routes>
        <Route path="/" element={<LanguageSelectionApp />} />
        <Route path="/:lang" element={<GameApp />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </Router>
  );
}

export default App;