import { useState, useCallback } from 'react';
import useLocalStorage from './useLocalStorage';

function useSound() {
  const [soundEnabled, setSoundEnabled] = useLocalStorage('soundEnabled', true);

  const playSound = useCallback((soundId) => {
    if (!soundEnabled) return;
    
    const audio = document.getElementById(soundId);
    if (audio) {
      audio.currentTime = 0;
      audio.play().catch(() => {
        // Ignore autoplay restrictions
      });
    }
  }, [soundEnabled]);

  const sounds = {
    matchSuccess: () => playSound('match-success-sound'),
    matchFail: () => playSound('match-fail-sound'),
    win: () => playSound('win-sound'),
    click: () => playSound('click-sound'),
    hint: (language = 'en') => {
      if (language !== 'en') {
        playSound(`hint-sound-${language}`);
      }
    },
    toast: (language = 'en') => playSound(`toast-sound-${language}`)
  };

  return {
    soundEnabled,
    setSoundEnabled,
    ...sounds
  };
}

export default useSound;