import { useState, useCallback, useEffect } from 'react';
import useLocalStorage from './useLocalStorage';
import { 
  generateSeededGrid, 
  isValidPairFlat, 
  findValidPairFlat, 
  isGameCompleteFlat, 
  addNumbers, 
  compactBoard 
} from '../utils/gameLogic';

function useGame() {
  const [gameState, setGameState] = useLocalStorage('gameState', null);
  const [bestScore, setBestScore] = useLocalStorage('bestScore', 0);
  const [selectedCellIndex, setSelectedCellIndex] = useState(null);
  const [showWin, setShowWin] = useState(false);
  const [showGameOver, setShowGameOver] = useState(false);
  const [showStageStart, setShowStageStart] = useState(false);
  const [hintHighlights, setHintHighlights] = useState([]);

  const initializeGame = useCallback((stage = 1) => {
    console.log('Initializing game for stage:', stage);
    const board = generateSeededGrid(stage);
    console.log('Generated board:', board.slice(0, 10));
    // Store initial board as a deep copy for retry functionality
    const initialBoard = board.map(cell => ({ ...cell }));
    const newGame = {
      board,
      initialBoard,
      stage,
      score: stage === 1 ? 0 : gameState?.score || 0,
      hintsLeft: stage >= 5 ? 5 : 3,
      addRowsLeft: 5
    };
    setGameState(newGame);
    setSelectedCellIndex(null);
    setHintHighlights([]);
    setShowWin(false);
    setShowGameOver(false);
    
    if (stage > 1) {
      setShowStageStart(true);
      setTimeout(() => setShowStageStart(false), 2000);
    }
    
    return newGame;
  }, [setGameState, gameState?.score]);

  const selectCell = useCallback((index) => {
    if (!gameState || !gameState.board[index] || gameState.board[index].state !== 'active') {
      return null;
    }
    
    // Clear hint highlights when user interacts
    if (hintHighlights.length > 0) {
      setHintHighlights([]);
    }
    
    if (selectedCellIndex === null) {
      setSelectedCellIndex(index);
      return null;
    } else {
      if (selectedCellIndex === index) {
        setSelectedCellIndex(null);
        return null;
      }
      
      const result = isValidPairFlat(gameState.board, selectedCellIndex, index, 9);
      setSelectedCellIndex(null);
      
      if (result.valid) {
        return { 
          cell1: selectedCellIndex, 
          cell2: index, 
          matchType: result.type 
        };
      } else {
        return { 
          error: true, 
          cell1: selectedCellIndex, 
          cell2: index, 
          blocking: result.blocking 
        };
      }
    }
  }, [gameState, selectedCellIndex, hintHighlights]);

  const processMatch = useCallback((cell1Index, cell2Index) => {
    if (!gameState) return false;
    
    // First show both cells as blue by setting tempSelected
    const tempBoard = [...gameState.board];
    tempBoard[cell1Index] = { ...tempBoard[cell1Index], tempSelected: true };
    tempBoard[cell2Index] = { ...tempBoard[cell2Index], tempSelected: true };
    
    setGameState({
      ...gameState,
      board: tempBoard
    });
    
    // After 300ms, process the actual match
    setTimeout(() => {
      const newBoard = [...gameState.board];
      newBoard[cell1Index] = { ...newBoard[cell1Index], state: 'blurred' };
      newBoard[cell2Index] = { ...newBoard[cell2Index], state: 'blurred' };
      delete newBoard[cell1Index].tempSelected;
      delete newBoard[cell2Index].tempSelected;
      
      const newScore = gameState.score + 10;
      
      // Compact the board after match
      const compactedBoard = compactBoard(newBoard);
      
      const updatedGameState = {
        ...gameState,
        board: compactedBoard,
        score: newScore
      };
      
      setGameState(updatedGameState);
      
      if (newScore > bestScore) {
        setBestScore(newScore);
      }
      
      // Check if game is complete
      if (isGameCompleteFlat(compactedBoard)) {
        setTimeout(() => setShowWin(true), 500);
      }
    }, 300);
    
    return true;
  }, [gameState, bestScore, setGameState, setBestScore]);

  const addRow = useCallback(() => {
    if (!gameState || gameState.addRowsLeft <= 0) return false;
    if (findValidPairFlat(gameState.board, 9)) return false; // Don't add if moves available
    
    const newBoard = addNumbers(gameState.board);
    
    setGameState({
      ...gameState,
      board: newBoard,
      addRowsLeft: gameState.addRowsLeft - 1
    });
    
    return true;
  }, [gameState, setGameState]);

  const useHint = useCallback(() => {
    if (!gameState || gameState.hintsLeft <= 0) return null;
    
    const pair = findValidPairFlat(gameState.board, 9);
    if (pair) {
      setGameState({
        ...gameState,
        hintsLeft: gameState.hintsLeft - 1
      });
      
      setHintHighlights(pair);
      return pair;
    }
    
    return null;
  }, [gameState, setGameState]);

  const checkGameOver = useCallback(() => {
    if (!gameState) return;
    
    const hasValidMovesLeft = findValidPairFlat(gameState.board, 9) !== null;
    
    if (!hasValidMovesLeft && gameState.addRowsLeft === 0) {
      setTimeout(() => setShowGameOver(true), 500);
    }
  }, [gameState]);

  useEffect(() => {
    if (gameState) {
      checkGameOver();
    }
  }, [gameState, checkGameOver]);

  const nextStage = useCallback(() => {
    setShowWin(false);
    // Add a small delay to ensure win modal is hidden before showing stage start
    setTimeout(() => {
      initializeGame(gameState.stage + 1);
    }, 100);
  }, [gameState?.stage, initializeGame]);

  const retryStage = useCallback(() => {
    setShowGameOver(false);
    initializeGame(gameState?.stage || 1);
  }, [gameState?.stage, initializeGame]);

  const retryCurrentGame = useCallback(() => {
    if (!gameState) return;
    
    // Convert all cells with values to active state without changing numbers
    const restoredBoard = gameState.board.map(cell => {
      if (cell.value !== null && cell.value !== undefined) {
        return { ...cell, state: 'active' };
      }
      return cell;
    });
    
    setGameState({
      ...gameState,
      board: restoredBoard,
      addRowsLeft: 5,
      hintsLeft: gameState.stage >= 5 ? 5 : 3
    });
    
    setSelectedCellIndex(null);
    setHintHighlights([]);
    setShowWin(false);
    setShowGameOver(false);
  }, [gameState, setGameState]);



  const goHome = useCallback(() => {
    setShowWin(false);
    setShowGameOver(false);
    setGameState(null);
  }, [setGameState]);

  return {
    gameState,
    bestScore,
    selectedCellIndex,
    hintHighlights,
    showWin,
    showGameOver,
    showStageStart,
    initializeGame,
    selectCell,
    processMatch,
    addRow,
    useHint,
    nextStage,
    retryStage,
    retryCurrentGame,
    goHome,
    clearSelection: () => {
      setSelectedCellIndex(null);
      setHintHighlights([]);
    },
    closeWin: () => setShowWin(false),
    closeGameOver: () => setShowGameOver(false),
    closeStageStart: () => setShowStageStart(false)
  };
}

export default useGame;