// Seeded random number generator for consistent grids per stage
export const seededRandom = (seed) => {
  let x = Math.sin(seed) * 10000;
  return x - Math.floor(x);
};

// Generate grid based on stage exactly like HTML version
export const generateSeededGrid = (stage = 1) => {
  const GAME_COLS = 9;
  let board = Array(GAME_COLS * 12).fill(null).map(() => ({ value: null, state: 'cleared' }));
  let initialNumbers;
  
  if (stage === 1) {
    const stage1Layout = [
      { value: 3, state: 'active' },   
      { value: 4, state: 'active' },   
      { value: 5, state: 'blurred' },  
      { value: 5, state: 'blurred' },  
      { value: 6, state: 'blurred' },  
      { value: 4, state: 'blurred' },  
      { value: 4, state: 'active' },   
      { value: 7, state: 'active' }    
    ];
    stage1Layout.forEach((cellData, i) => {
      board[i] = cellData;
    });
    return board;
  }

  if (stage === 2) {
    // 60% same pairs, 40% sum-to-10 pairs
    const samePairs = [];
    const sumPairs = [];
    
    // Generate same pairs (60% = ~22 numbers = 11 pairs)
    for(let i = 1; i <= 9; i++) {
      if(samePairs.length < 22) {
        samePairs.push(i, i);
      }
    }
    // Fill remaining same pairs
    while(samePairs.length < 22) {
      const num = Math.floor(Math.random() * 9) + 1;
      samePairs.push(num, num);
    }
    
    // Generate sum-to-10 pairs (40% = ~14 numbers = 7 pairs)
    const sumCombos = [[1,9], [2,8], [3,7], [4,6]];
    while(sumPairs.length < 14) {
      const combo = sumCombos[Math.floor(Math.random() * sumCombos.length)];
      sumPairs.push(combo[0], combo[1]);
    }
    
    initialNumbers = [...samePairs, ...sumPairs];
    // Shuffle the array
    for (let i = initialNumbers.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [initialNumbers[i], initialNumbers[j]] = [initialNumbers[j], initialNumbers[i]];
    }
  } else {
    let pairs = [];
    for(let k=0; k<4; k++) {
      for(let i=1; i<=9; i++) pairs.push(i,i);
      for(let i=1; i<=9; i++) pairs.push(i, 10-i);
    }
    for (let i = pairs.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [pairs[i], pairs[j]] = [pairs[j], pairs[i]];
    }
    initialNumbers = pairs.slice(0, 36);
  }
  
  initialNumbers.forEach((num, i) => {
    board[i] = { value: num, state: 'active' };
  });
  return board;
};

// Get stage configuration - Always 9x9 grid
export const getStageConfig = (stage) => {
  const rows = 9;
  const cols = 9;
  
  let hints;
  if (stage <= 3) {
    hints = 3;
  } else if (stage <= 6) {
    hints = 4;
  } else {
    hints = 5;
  }
  
  return { rows, cols, hints };
};

// Advanced path validation with clear path checking
export const isValidPath = (cell1, cell2, grid, matchedCells = []) => {
  // Check if cells are matched
  const isMatched = (r, c) => matchedCells.includes(`${r}-${c}`);
  
  if (isMatched(cell1.row, cell1.col) || isMatched(cell2.row, cell2.col)) {
    return false;
  }
  
  // Same row - check for clear path
  if (cell1.row === cell2.row) {
    const minCol = Math.min(cell1.col, cell2.col);
    const maxCol = Math.max(cell1.col, cell2.col);
    for (let col = minCol + 1; col < maxCol; col++) {
      if (!isMatched(cell1.row, col)) {
        return false;
      }
    }
    return true;
  }
  
  // Same column - check for clear path
  if (cell1.col === cell2.col) {
    const minRow = Math.min(cell1.row, cell2.row);
    const maxRow = Math.max(cell1.row, cell2.row);
    for (let row = minRow + 1; row < maxRow; row++) {
      if (!isMatched(row, cell1.col)) {
        return false;
      }
    }
    return true;
  }
  
  // Diagonal matching - directly diagonal cells (one row after the other)
  const diagonalConnection = canConnectDiagonal(cell1, cell2, grid, matchedCells);
  if (diagonalConnection) return true;
  
  // Edge-to-edge connection between rows
  const edgeConnection = canConnectEdgeToEdge(cell1, cell2, grid, matchedCells);
  if (edgeConnection) return true;
  
  // L-shaped path validation
  const path1Valid = canConnectLShaped(cell1, cell2, grid, matchedCells, 'horizontal-first');
  const path2Valid = canConnectLShaped(cell1, cell2, grid, matchedCells, 'vertical-first');
  
  return path1Valid || path2Valid;
};

// Check diagonal connection - directly diagonal cells
const canConnectDiagonal = (cell1, cell2, grid, matchedCells) => {
  const rowDiff = Math.abs(cell1.row - cell2.row);
  const colDiff = Math.abs(cell1.col - cell2.col);
  
  // Must be exactly one row and one column apart (directly diagonal)
  if (rowDiff === 1 && colDiff === 1) {
    return true;
  }
  
  return false;
};

// Check edge-to-edge connection between rows
const canConnectEdgeToEdge = (cell1, cell2, grid, matchedCells) => {
  const isMatched = (r, c) => matchedCells.includes(`${r}-${c}`);
  
  // Check if one cell is at the end of a row and the other at the beginning of another row
  const isRightEdge = (row, col) => col === grid[0].length - 1;
  const isLeftEdge = (row, col) => col === 0;
  
  // Case 1: cell1 at right edge, cell2 at left edge of different row
  if (isRightEdge(cell1.row, cell1.col) && isLeftEdge(cell2.row, cell2.col) && cell1.row !== cell2.row) {
    // Check if ALL numbers between cell1 and right edge are matched (blocked)
    for (let col = cell1.col + 1; col < grid[0].length; col++) {
      if (!isMatched(cell1.row, col)) return false;
    }
    // Check if ALL numbers between left edge and cell2 are matched (blocked)
    for (let col = 0; col < cell2.col; col++) {
      if (!isMatched(cell2.row, col)) return false;
    }
    return true;
  }
  
  // Case 2: cell2 at right edge, cell1 at left edge of different row
  if (isRightEdge(cell2.row, cell2.col) && isLeftEdge(cell1.row, cell1.col) && cell1.row !== cell2.row) {
    // Check if ALL numbers between cell2 and right edge are matched (blocked)
    for (let col = cell2.col + 1; col < grid[0].length; col++) {
      if (!isMatched(cell2.row, col)) return false;
    }
    // Check if ALL numbers between left edge and cell1 are matched (blocked)
    for (let col = 0; col < cell1.col; col++) {
      if (!isMatched(cell1.row, col)) return false;
    }
    return true;
  }
  
  return false;
};

// Check L-shaped connection
const canConnectLShaped = (cell1, cell2, grid, matchedCells, direction) => {
  const isMatched = (r, c) => {
    if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length) return true;
    return matchedCells.includes(`${r}-${c}`);
  };
  
  if (direction === 'horizontal-first') {
    // Try horizontal then vertical
    const cornerRow = cell1.row;
    const cornerCol = cell2.col;
    
    // Check horizontal path from cell1 to corner
    const minCol = Math.min(cell1.col, cornerCol);
    const maxCol = Math.max(cell1.col, cornerCol);
    for (let col = minCol + 1; col < maxCol; col++) {
      if (!isMatched(cornerRow, col)) return false;
    }
    
    // Check vertical path from corner to cell2
    const minRow = Math.min(cornerRow, cell2.row);
    const maxRow = Math.max(cornerRow, cell2.row);
    for (let row = minRow + 1; row < maxRow; row++) {
      if (!isMatched(row, cornerCol)) return false;
    }
    
    // Check if corner is clear (unless it's one of our cells)
    if (cornerRow !== cell1.row || cornerCol !== cell1.col) {
      if (cornerRow !== cell2.row || cornerCol !== cell2.col) {
        if (!isMatched(cornerRow, cornerCol)) return false;
      }
    }
    
    return true;
  } else {
    // Try vertical then horizontal
    const cornerRow = cell2.row;
    const cornerCol = cell1.col;
    
    // Check vertical path from cell1 to corner
    const minRow = Math.min(cell1.row, cornerRow);
    const maxRow = Math.max(cell1.row, cornerRow);
    for (let row = minRow + 1; row < maxRow; row++) {
      if (!isMatched(row, cornerCol)) return false;
    }
    
    // Check horizontal path from corner to cell2
    const minCol = Math.min(cornerCol, cell2.col);
    const maxCol = Math.max(cornerCol, cell2.col);
    for (let col = minCol + 1; col < maxCol; col++) {
      if (!isMatched(cornerRow, col)) return false;
    }
    
    // Check if corner is clear
    if (cornerRow !== cell1.row || cornerCol !== cell1.col) {
      if (cornerRow !== cell2.row || cornerCol !== cell2.col) {
        if (!isMatched(cornerRow, cornerCol)) return false;
      }
    }
    
    return true;
  }
};

// Get match type for visualization
export const getMatchType = (cell1, cell2, grid, matchedCells = []) => {
  const isMatched = (r, c) => matchedCells.includes(`${r}-${c}`);
  
  if (isMatched(cell1.row, cell1.col) || isMatched(cell2.row, cell2.col)) {
    return null;
  }
  
  // Same row
  if (cell1.row === cell2.row) {
    return 'horizontal';
  }
  
  // Same column
  if (cell1.col === cell2.col) {
    return 'vertical';
  }
  
  // Diagonal
  if (canConnectDiagonal(cell1, cell2, grid, matchedCells)) {
    return 'diagonal';
  }
  
  // Edge connection
  if (canConnectEdgeToEdge(cell1, cell2, grid, matchedCells)) {
    return 'edge';
  }
  
  // L-shaped
  if (canConnectLShaped(cell1, cell2, grid, matchedCells, 'horizontal-first') ||
      canConnectLShaped(cell1, cell2, grid, matchedCells, 'vertical-first')) {
    return 'l-shaped';
  }
  
  return null;
};

export const isValidMatch = (cell1, cell2, grid, matchedCells = []) => {
  const valueMatch = cell1.value === cell2.value || cell1.value + cell2.value === 10;
  const pathValid = isValidPath(cell1, cell2, grid, matchedCells);
  return valueMatch && pathValid;
};

// Check if board cell is valid for matching (active state)
export const isCellActive = (board, index) => {
  return board[index] && board[index].state === 'active';
};

// Convert flat board index to row/col
export const indexToRowCol = (index, cols = 9) => {
  return {
    row: Math.floor(index / cols),
    col: index % cols
  };
};

// Convert row/col to flat board index
export const rowColToIndex = (row, col, cols = 9) => {
  return row * cols + col;
};

export const findValidPairs = (grid, matchedCells = []) => {
  const pairs = [];
  
  for (let i = 0; i < grid.length; i++) {
    for (let j = 0; j < grid[i].length; j++) {
      if (matchedCells.includes(`${i}-${j}`)) continue;
      
      for (let x = 0; x < grid.length; x++) {
        for (let y = 0; y < grid[x].length; y++) {
          if (x === i && y === j) continue;
          if (matchedCells.includes(`${x}-${y}`)) continue;
          
          const cell1 = { row: i, col: j, value: grid[i][j] };
          const cell2 = { row: x, col: y, value: grid[x][y] };
          
          if (isValidMatch(cell1, cell2, grid, matchedCells)) {
            pairs.push([cell1, cell2]);
          }
        }
      }
    }
  }
  
  return pairs;
};

// Find valid pairs for flat board structure like HTML version
export const findValidPairsFlat = (board, cols = 9) => {
  if (!board || !Array.isArray(board)) return [];
  
  const activeCells = [];
  board.forEach((cell, i) => { 
    if(cell && cell.state === 'active') activeCells.push(i); 
  });
  
  const validPairs = [];
  for (let i = 0; i < activeCells.length; i++) {
    for (let j = i + 1; j < activeCells.length; j++) {
      if (isValidPairFlat(board, activeCells[i], activeCells[j], cols).valid) {
        validPairs.push([activeCells[i], activeCells[j]]);
      }
    }
  }
  return validPairs;
};

// Check if two flat board indices form a valid pair
export const isValidPairFlat = (board, index1, index2, cols = 9) => {
  if (!board || !board[index1] || !board[index2]) return { valid: false, blocking: [] };
  
  const num1 = board[index1].value;
  const num2 = board[index2].value;
  if (num1 !== num2 && num1 + num2 !== 10) return { valid: false, blocking: [] };

  const r1 = Math.floor(index1 / cols), c1 = index1 % cols;
  const r2 = Math.floor(index2 / cols), c2 = index2 % cols;
  let blocking = [];

  // Same row - horizontal match
  if (r1 === r2) {
    for (let c = Math.min(c1, c2) + 1; c < Math.max(c1, c2); c++) {
      if (board[r1 * cols + c].state === 'active') blocking.push(r1 * cols + c);
    }
    if (blocking.length > 0) return { valid: false, blocking: blocking };
    return { valid: true, type: 'horizontal', blocking: [] };
  }

  // Same column - vertical match
  if (c1 === c2) {
    for (let r = Math.min(r1, r2) + 1; r < Math.max(r1, r2); r++) {
      if (board[r * cols + c1].state === 'active') blocking.push(r * cols + c1);
    }
    if (blocking.length > 0) return { valid: false, blocking: blocking };
    return { valid: true, type: 'vertical', blocking: [] };
  }
  
  // Diagonal match
  if (Math.abs(r1 - r2) === Math.abs(c1 - c2)) {
    const rStep = r1 < r2 ? 1 : -1;
    const cStep = c1 < c2 ? 1 : -1;
    let currR = r1 + rStep;
    let currC = c1 + cStep;
    while (currR !== r2) {
      if (board[currR * cols + currC].state === 'active') blocking.push(currR * cols + currC);
      currR += rStep;
      currC += cStep;
    }
    if (blocking.length > 0) return { valid: false, blocking: blocking };
    return { valid: true, type: 'diagonal', blocking: [] };
  }
  
  // Sequential match (active cells next to each other in sequence) - edge-to-edge matching
  const activeIndices = [];
  board.forEach((cell, i) => { if(cell && cell.state === 'active') activeIndices.push(i); });
  const pos1 = activeIndices.indexOf(index1);
  const pos2 = activeIndices.indexOf(index2);
  
  if (pos1 !== -1 && pos2 !== -1 && Math.abs(pos1 - pos2) > 0) {
    // Check if there are blocking cells between the two positions in sequence
    for (let i = Math.min(pos1, pos2) + 1; i < Math.max(pos1, pos2); i++) {
      blocking.push(activeIndices[i]);
    }
    if (blocking.length > 0) return { valid: false, blocking: blocking };
  }
  
  // If positions are adjacent (difference of 1), it's a valid sequential match
  if (pos1 !== -1 && pos2 !== -1 && Math.abs(pos1 - pos2) === 1) {
    return { valid: true, type: 'sequential', blocking: [] };
  }

  return { valid: false, blocking: [] };
};

// Find a single valid pair for hints
export const findValidPairFlat = (board, cols = 9) => {
  if (!board || !Array.isArray(board)) return null;
  
  const activeCells = [];
  board.forEach((cell, i) => { 
    if(cell && cell.state === 'active') activeCells.push(i); 
  });
  
  for(let i=0; i<activeCells.length; i++) {
    for(let j=i+1; j<activeCells.length; j++) {
      if(isValidPairFlat(board, activeCells[i], activeCells[j], cols).valid) {
        return [activeCells[i], activeCells[j]];
      }
    }
  }
  return null;
};

export const isGameComplete = (grid, matchedCells) => {
  const totalCells = grid.length * grid[0].length;
  return matchedCells.length === totalCells;
};

// Check if flat board game is complete
export const isGameCompleteFlat = (board) => {
  if (!board || !Array.isArray(board)) return false;
  return board.every(c => c && c.state !== 'active');
};

// Check if flat board has valid moves
export const hasValidMovesFlat = (board, cols = 9) => {
  if (!board || !Array.isArray(board)) return false;
  return findValidPairFlat(board, cols) !== null;
};

export const hasValidMoves = (grid, matchedCells) => {
  return findValidPairs(grid, matchedCells).length > 0;
};

// Add numbers function like HTML version
export const addNumbers = (board) => {
  if (!board || !Array.isArray(board)) return [];
  
  const remainingActiveValues = board.filter(c => c && c.state === 'active').map(c => c.value);
  
  let lastPopulatedIndex = -1;
  for (let i = board.length - 1; i >= 0; i--) {
    if (board[i].state !== 'cleared') {
      lastPopulatedIndex = i;
      break;
    }
  }

  let currentIndex = lastPopulatedIndex + 1;
  const newBoard = [...board];
  
  for(let i = 0; i < remainingActiveValues.length; i++) {
    if(currentIndex < newBoard.length) {
      newBoard[currentIndex] = { value: remainingActiveValues[i], state: 'active' };
      currentIndex++;
    }
  }
  
  return newBoard;
};

// Compact board by removing empty rows exactly like HTML version
export const compactBoard = (board, cols = 9) => {
  if (!board || !Array.isArray(board)) return [];
  
  const newBoard = [];
  for (let i = 0; i < board.length; i += cols) {
    const row = board.slice(i, i + cols);
    if (!row.every(cell => cell && (cell.state === 'blurred' || cell.state === 'cleared'))) {
      newBoard.push(...row);
    }
  }
  // Ensure we maintain the same board size as HTML (9x12 = 108 cells)
  while(newBoard.length < board.length) {
    newBoard.push({ value: null, state: 'cleared' });
  }
  return newBoard;
};